(window.EX_CHUNKS=window.EX_CHUNKS||{})["b16"]={"文具":[["我买了很多漂亮的文具。","مەن نۇرغۇن چىرايلىق يازغۇچىلىق بۇيۇملىرىنى سېتىۋالدىم.","men nurghun chirayliq yazghuchiliq buyumlirini sétiwaldim."]],"保重":[["出门在外，你要多保重身体。","سەپەردە يۈرگەندە، ئۆز بەدىنىڭىزنى كۆپرەك ئاسرىشىڭىز كېرەك.","seperde yürgende, öz bediningizni köprek asrishingiz kérek."]],"仓促":[["由于准备仓促，活动进行得并不顺利。","تەييارلىق ئالدىراش بولغانلىقى ئۈچۈن، پائالىيەت ئوڭۇشلۇق ئېلىپ بېرىلمىدى.","teyyarliq aldirash bolghanliqi üchün, paaliyet ongushluq élip bérilmidi."]],"根深蒂固":[["这种观念已经根深蒂固，难以改变。","بۇ تۈشۈنچە ئاللىبۇرۇن يىلتىز تارتىپ كەتكەن، ئۆزگەرتىش قىيىن.","bu tüshünche alliburun yiltiz tartip ketken, özgertish qiyin."]],"迁就":[["不要迁就他的无理要求。","ئۇنىڭ ئورۇنسىز تەلەپلىرىگە يول قويماڭ.","uning orunsiz teleplirige yol qoymang."]],"泄气":[["别泄气，失败是成功之母！","رۇھىڭىزنى چۈشۈرمەڭ، مەغلۇبىيەت مۇۋەپپەقىيەتنىڭ ئانىسىدۇر!","ruhingizni chüshürmeng, meghlubiyet muweppeqiyetning anisidur!"]],"堐":[["堐沟里长满了杂草。","چاڭگۇ ئېرىقىدا بەتچە ئوت-چۆپ ئۆسۈپ كەتكەن.","changgu ériqida betche ot-chöp ösüp ketken."]],"墐":[["小屋的墐是用泥巴做的。","كىچىك ئۆينىڭ تامى لايدىن ياسالغان.","kichik öyning tami laydin yasalghan."]],"攐":[["他攐起袖子，开始工作。","ئۇ يەڭلىرىنى تۈرۈپ، خىزمەتكە كىرىشتى.","u yenglirini türüp, xizmetke kirishti."]],"梐":[["梐木的质地坚硬耐用。","بى ياغىچىنىڭ سۈپىتى قاتتىق ۋە چىداملىق.","bi yaghichining süpiti qattiq we chidamliq."]],"欐":[["欐木的香气独特。","لىيەن ياغىچىنىڭ ھىدى ئالاھىدە.","liyen yaghichining hidi alahide."]],"澐":[["溪水流过岩石，发出澐澐的声响。","ئېقىن تاشلاردىن ئېقىپ، شىلدىرلىغان ئاۋاز چىقاردى.","éqin tashlardin éqip, shildirlighan awaz chiqardi."]],"祐":[["神灵祐护国家安宁。","ئىلاھلار دۆلەتنىڭ تىنچلىقىنى قوغدايدۇ.","ilahlar döletning tinchliqini qoghdaydu."]],"繐":[["繐布用于制作祭祀的祭品。","سۈي رەختى قۇربانلىق مەرىكىسىدە ئىشلىتىلىدۇ.","süy rexti qurbanliq merikiside ishlitilidu."]],"菐":[["这种植物叫菐，常用于中药。","بۇ ئۆسۈملۈك كۈنچىقار دەپ ئاتىلىدۇ، كۆپىنچە جۇڭگو تېبابىتىدە ئىشلىتىلىدۇ.","bu ösümlük künchiqar dep atilidu, köpinche junggo tébabitide ishlitilidu."]],"鑐":[["门上的鑐环已经锈迹斑斑。","ئىشىكتىكى ھالقا تاتلىق توتقا تولغان.","ishiktiki halqa tatliq totqa tolghan."]],"饐":[["这个饐菜有点咸了。","بۇ تائام بىر ئاز تۇزلۇق بولۇپ قاپتۇ.","bu taam bir az tuzluq bolup qaptu."]],"鱐":[["鱐鱼属于小型海鱼。","سۇ بېلىقى كىچىك تىپتىكى دېڭىز بېلىقىغا تەۋە.","su béliqi kichik tiptiki déngiz béliqigha tewe."]],"一个人":[["他一个人完成了整个项目。","ئۇ پۈتۈن تۈرنى ئۆزى يالغۇز تاماملىدى.","u pütün türni özi yalghuz tamamlidi."]],"一席话":[["一席话让他改变了主意。","بىر سۆز ئۇنىڭ پىكرىنى ئۆزگەرتتى.","bir söz uning pikrini özgertti."]],"一声不响":[["他一声不响地坐在那里。","ئۇ ھېچقانداق ئاۋاز چىقارماي ئۇ يەردە ئولتۇردى.","u héchqandaq awaz chiqarmay u yerde olturdi."]],"一股脑":[["他一股脑把所有事情都说了出来。","ئۇ ھەممە ئىشنى بىرلا ئېغىزدىن سۆزلەپ بەردى.","u hemme ishni birla éghizdin sözlep berdi."]],"一脉相承":[["这个传统一脉相承，从未中断。","بۇ ئەنئەنە بىر زەنجىردە داۋاملىشىپ كەلدى، ھەرگىز ئۈزۈلۈپ قالغىنى يوق.","bu en'ene bir zenjirde dawamliship keldi, hergiz üzülüp qalghini yoq."]],"一转眼":[["一转眼，十年过去了。","كۆز ئاچقۇچە ئون يىل ئۆتۈپ كەتتى.","köz achquche on yil ötüp ketti."]],"三星堆":[["三星堆是四川的一个考古遗址。","سەنسىڭدۇي سىچۈەندىكى بىر ئارخېئولوگىيەلىك خارابە.","sensingduy sichüendiki bir arxéologiyelik xarabe."]],"三曹":[["三曹指曹操、曹丕、曹植。","سەنچاۋ ساۋساۋ، ساۋپى، ساۋجىنى كۆرسىتىدۇ.","senchaw sawsaw, sawpi, sawjini körsitidu."]],"三氯氰胺":[["三氯氰胺是一种高效的除草剂。","ئۈچ خلورلۇق سىيانامىد ئۈنۈملۈك بىر ئوت-چۆپ يوقىتىش دورىسىدۇر.","üch xlorluq siyanamid ünümlük bir ot-chöp yoqitish dorisidur."]],"三角龙":[["三角龙是史前的一种恐龙。","ترىسېراتوپس قەدىمكى زاماندىكى بىر خىل دىنوزاۋردۇر.","trisératops qedimki zamandiki bir xil dinozawrdur."]],"三项":[["比赛包含三项内容。","مۇسابىقە ئۈچ مەزمۇننى ئۆز ئىچىگە ئالىدۇ.","musabiqe üch mezmunni öz ichige alidu."]],"不好":[["这个主意不好，可能会出问题。","بۇ پىكىر ياخشى ئەمەس، مەسىلە كېلىپ چىقىشى مۇمكىن.","bu pikir yaxshi emes, mesile kélip chiqishi mumkin."]],"不怎么样":[["这道菜味道不怎么样，有点淡。","بۇ تائامنىڭ تەمى ئانچە ياخشى ئەمەس، سەل تاتلىق.","bu taamning temi anche yaxshi emes, sel tatliq."]],"不尽":[["他的故事讲不尽，让人听不够。","ئۇنىڭ ھېكايىسى تۈگىمەيدۇ، كىشىنىڭ ئاڭلىغۇسى كېلىپ تۇرىدۇ.","uning hékayisi tügimeydu, kishining anglighusi kélip turidu."]],"不能":[["这件事他不能接受。","بۇ ئىشنى ئۇ قوبۇل قىلالمايدۇ.","bu ishni u qobul qilalmaydu."]],"不爽":[["他今天看起来很不爽。","ئۇ بۈگۈن كەيپىياتى ناھايىتى ناچار كۆرۈنىدۇ.","u bügün keypiyati nahayiti nachar körünidu."]],"世界末日":[["世界末日令人感到恐惧。","دۇنيا ئاخىرىتى ئادەملەرنى قورقۇنچقا سالىدۇ.","dunya axiriti ademlerni qorqunchqa salidu."]],"丢面子":[["这次失败让他很丢面子。","بۇ مەغلۇبىيەت ئۇنىڭ يۈزىنى يەرگە قىلدى.","bu meghlubiyet uning yüzini yerge qildi."]],"丙等":[["丙等成绩属于中等水平。","بىڭ دەرىجىلىك نەتىجە ئوتتۇرا سەۋىيەگە تەۋە.","bing derijilik netije ottura sewiyege tewe."]],"中国航天工业公司":[["中国航天工业公司成功发射了卫星。","جۇڭگو ئالەم ئايروپىلان سانائىتى شىركىتى ھەمراھنى مۇۋەپپەقىيەتلىك ئۇچۇردى.","junggo alem ayropilan sanaiti shirkiti hemrahni muweppeqiyetlik uchurdi."]],"中朝":[["中朝两国友谊深厚。","جۇڭگو ۋە چاۋشيەن ئىككى دۆلەتنىڭ دوستلۇقى چوڭقۇر.","junggo we chawshyen ikki döletning dostluqi chongqur."]],"中川":[["中川是一条流经日本的城市河流。","جۇڭچۈەن ياپونىيەدىن ئېقىپ ئۆتىدىغان شەھەر دەرياسىدۇر.","jungchüen yaponiyedin éqip ötidighan sheher deryasidur."]],"二尖瓣狭窄":[["二尖瓣狭窄会导致心脏功能异常。","ئىككى تەرەپلىك قاپقاق تارلىقى يۈرەك ئىقتىدارىنىڭ نورمالسىزلىقىغا سەۋەب بولىدۇ.","ikki tereplik qapqaq tarliqi yürek iqtidarining normalsizliqigha seweb bolidu."]],"干裂":[["干燥的气候导致嘴唇干裂，需要涂抹润唇膏。","قۇرغاق ھاۋا كالپۇكنىڭ يېرىلىشىنى كەلتۈرۈپ چىقىرىدۇ، لەۋ سۈركىمەسى سۈركەش كېرەك.","qurghaq hawa kalpukning yérilishini keltürüp chiqiridu, lew sürkimesi sürkesh kérek."]],"互换":[["两人互换了礼物。","ئىككىيلەن سوۋغات ئالماشتۇردى.","ikkiylen sowghat almashturdi."]],"亚太":[["亚太地区是全球经济增长的重要引擎。","ئاسىيا-تىنچ ئوكيان رايونى دۇنيا ئىقتىسادىي ئۆسۈشىنىڭ مۇھىم ماتورىدۇر.","asiya-tinch okyan rayoni dunya iqtisadiy ösüshining muhim matoridur."]],"交通肇事罪":[["交通肇事罪需承担刑事责任。","قاتناش ھادىسىسى جىنايىتى جىنايى جاۋابكارلىقنى ئۈستىگە ئېلىشنى تەلەپ قىلىدۇ.","qatnash hadisisi jinayiti jinayi jawabkarliqni üstige élishni telep qilidu."]],"人工岛":[["这座人工岛正在建设中。","بۇ سۈنئىي ئارال قۇرۇلۇش جەريانىدا.","bu sün'iy aral qurulush jeryanida."]],"人满为患":[["节假日景区总是人满为患。","بايرام كۈنلىرى مەنزىرە رايونلىرىدا ئادەم ھەمىشە لىق تولىدۇ.","bayram künliri menzire rayonlirida adem hemishe liq tolidu."]],"人民警察":[["人民警察为人民的生命财产安全负责。","خەلق ساقچىلىرى خەلقنىڭ ھاياتى ۋە مال-مۈلۈك بىخەتەرلىكى ئۈچۈن مەسئۇلىيەتچان.","xelq saqchiliri xelqning hayati we mal-mülük bixeterliki üchün mes'uliyetchan."]],"仁爱":[["她以仁爱之心对待每一个人。","ئۇ ھەر بىر ئادەمگە مېھرىبانلىق قەلبى بىلەن مۇئامىلە قىلىدۇ.","u her bir ademge méhribanliq qelbi bilen muamile qilidu."]],"今晚":[["今晚我们一起去吃火锅吧。","بۈگۈن كەچتە بىرلىكتە قازانغا گۆش سالىمىزغا بارايلى.","bügün kechte birlikte qazangha gösh salimizgha barayli."]],"仙草":[["仙草在传说中拥有治愈百病的功效。","شىيەنچاۋ رىۋايەتلەردە يۈز كېسەلنى ساقايتىش كۈچىگە ئىگە.","shiyenchaw riwayetlerde yüz késelni saqaytish küchige ige."]],"仵工":[["仵工协助仵作完成尸检工作。","جىنايەت تەكشۈرگۈچى ياردەمچىسى جەسەت تەكشۈرۈش خىزمىتىنى تاماملاشقا ياردەم بېرىدۇ.","jinayet tekshürgüchi yardemchisi jeset tekshürüsh xizmitini tamamlashqa yardem béridu."]],"伊通":[["伊通是吉林省的一个城市。","ئىتۇڭ جىلىن ئۆلكىسىدىكى بىر شەھەر.","itung jilin ölkisidiki bir sheher."]],"伊党":[["伊党是历史上的政治派系。","ئىپارتىيە تارىختىكى سىياسىي گۇرۇھ.","ipartiye tarixtiki siyasiy guruh."]],"伏线":[["故事中的伏线贯穿整个情节。","ھېكايەدىكى يوشۇرۇن يىپ پۈتۈن سۈژېتكە سىڭىپ كەتكەن.","hékayediki yoshurun yip pütün süzhétke singip ketken."]],"佛罗里达州":[["佛罗里达州是美国人口最多的州之一。","فىلورىدا ئىشتاتى ئامېرىكىدىكى نوپۇسى ئەڭ كۆپ ئىشتاتلارنىڭ بىرى.","filorida ishtati amérikidiki nopusi eng köp ishtatlarning biri."]],"佛兰芒语":[["佛兰芒语是比利时的主要语言之一。","فلامان تىلى بېلگىيەنىڭ ئاساسلىق تىللىرىنىڭ بىرى.","flaman tili bélgiyening asasliq tillirining biri."]],"作马":[["他甘愿作马，任劳任怨。","ئۇ ئات بولۇشقا خۇشال، جاپاغا چىداپ ئىشلەيدۇ.","u at bolushqa xushal, japagha chidap ishleydu."]],"佛朗机炮":[["佛朗机炮是明代使用的重型火炮。","فرانكى توپى مىڭ سۇلالىسى دەۋرىدە ئىشلىتىلگەن ئېغىر توپتۇر.","franki topi ming sulalisi dewride ishlitilgen éghir toptur."]],"似曾相识":[["这句话让我有种似曾相识的感觉。","بۇ جۈملە ماڭا بىرەر يەردە كۆرگەندەك تۇيغۇ بەردى.","bu jümle manga birer yerde körgendek tuyghu berdi."]],"侏儒仓鼠":[["侏儒仓鼠是常见的宠物动物。","پاكار چاشقان ئۆي ھايۋانلىرى ئىچىدە كۆپ ئۇچرايدىغان بىر ھايۋاندۇر.","pakar chashqan öy haywanliri ichide köp uchraydighan bir haywandur."]],"便是":[["这便是我们常说的方法。","بۇ بىز دائىم ئېيتىدىغان ئۇسۇلدۇر.","bu biz daim éytidighan usuldur."]],"信用危机":[["这场信用危机影响了多家企业。","بۇ ئىشەنچ ئىناۋىتى كرىزىسى نۇرغۇن كارخانىلارغا تەسىر كۆرسەتتى.","bu ishench inawiti krizisi nurghun karxanilargha tesir körsetti."]],"信天游":[["信天游是中国西北地区的民歌。","شىنتيەنيۇ جۇڭگونىڭ شىمالىي غەربىي رايونىنىڭ خەلق ناخشىسى.","shintyenyu junggoning shimaliy gherbiy rayonining xelq naxshisi."]],"信息图":[["信息图用视觉方式呈现复杂数据。","ئۇچۇر گرافىكى مۇرەككەپ سانلىق مەلۇماتلارنى كۆرۈش ئۇسۇلى بىلەن نامايان قىلىدۇ.","uchur grafiki murekkep sanliq melumatlarni körüsh usuli bilen namayan qilidu."]],"信阳市":[["信阳市是河南省的重要城市。","شىنياڭ شەھىرى خېنەن ئۆلكىسىنىڭ مۇھىم شەھىرى.","shinyang shehiri xénen ölkisining muhim shehiri."]],"修图":[["我用软件修图，让照片更清晰。","مەن يۇمشاق دېتال ئارقىلىق سۈرەتنى تۈزىتىپ، فوتوگرافىيەنى تېخىمۇ ئېنىق قىلدىم.","men yumshaq détal arqiliq süretni tüzitip, fotografiyeni téximu éniq qildim."]],"修造厂":[["修造厂为设备提供维修服务。","رېمونت زاۋۇتى ئۈسكۈنىلەرگە رېمونت مۇلازىمىتى تەمىنلەيدۇ.","rémont zawuti üskünilerge rémont mulazimiti teminleydu."]],"偏西":[["太阳已经偏西，天色渐暗。","قۇياش غەربكە ئېغىپ بولدى، ئاسمان ئاستا-ئاستا قاراڭغۇلاشتى.","quyash gherbke éghip boldi, asman asta-asta qarangghulashti."]],"傅立叶":[["傅立叶在数学领域有贡献。","فۇرىيې ماتېماتىكا ساھەسىدە تۆھپە قوشتى.","furiyé matématika saheside töhpe qoshti."]],"催逼":[["他的催逼让对手感到压力。","ئۇنىڭ ئالدىرىتىشى رەقىبىگە بېسىم ئېلىپ كەلدى.","uning aldiritishi reqibige bésim élip keldi."]],"借住":[["他暂时借住在我家几天。","ئۇ مۇۋەققەت مېنىڭ ئۆيۈمدە bir neçə كۈن تۇرۇپ قالدى.","u muweqqet méning öyümde bir neçə kün turup qaldi."]],"借记卡":[["请使用借记卡支付。","تۆلەم قىلىش ئۈچۈن دىبېت كارتىسىنى ئىشلىتىڭ.","tölem qilish üchün dibét kartisini ishliting."]],"传述":[["他传述了古代的历史故事。","ئۇ قەدىمكى تارىخىي ھېكايىلەرنى رىۋايەت قىلدى.","u qedimki tarixiy hékayilerni riwayet qildi."]],"充电":[["手机需要充电才能继续使用。","تېلېفوننى داۋاملىق ئىشلىتىش ئۈچۈن قاچىلاش كېرەك.","téléfonni dawamliq ishlitish üchün qachilash kérek."]],"元阳":[["元阳以哈尼梯田景观著称。","يۈەنيەڭ خەنىزۇ تېرەسسا مەنزىرىسى بىلەن داڭلىق.","yüenyeng xenizu téressa menzirisi bilen dangliq."]],"元音":[["元音是发音时气流不受阻碍的音。","يۈەنيىن تەلەپپۇز قىلغاندا ھاۋا ئېقىمى توسالغۇغا ئۇچرىمايدىغان ئاۋاز.","yüenyin teleppuz qilghanda hawa éqimi tosalghugha uchrimaydighan awaz."]],"克汀病":[["克汀病会导致严重的发育障碍。","كرېتىنىزم كېسىلى ئېغىر تەرەققىيات توسالغۇسىنى كەلتۈرۈپ چىقىرىدۇ.","krétinizm késili éghir tereqqiyat tosalghusini keltürüp chiqiridu."]],"光禄勋":[["光禄勋是古代的一种官职。","گۇاڭلۇشۈن قەدىمكى زاماندىكى بىر خىل ئەمەلدارلىق ئورنى.","guanglushün qedimki zamandiki bir xil emeldarliq orni."]],"八分之一":[["八分之一是分数中的基本单位。","سەككىزدىن بىر قىسىم ئۇسۇل ئىچىدىكى ئاساسىي بىرلىك.","sekkizdin bir qisim usul ichidiki asasiy birlik."]],"两头":[["他两头都兼顾，忙得不可开交。","ئۇ ئىككى تەرەپنىڭ ھەممىسىنى كۆزدە تۇتۇپ، ئىنتايىن ئالدىراش.","u ikki terepning hemmisini közde tutup, intayin aldirash."]],"六朝":[["六朝时期文化繁荣。","ئالتە سۇلالە دەۋرىدە مەدەنىيەت گۈللەندى.","alte sulale dewride medeniyet güllendi."]],"再好":[["这个方案再好，也有改进空间。","بۇ پىلان قانچىلىك ياخشى بولسىمۇ، يەنىلا ياخشىلاش بوشلۇقى بار.","bu pilan qanchilik yaxshi bolsimu, yenila yaxshilash boshluqi bar."]],"公开指责":[["他公开指责对方的错误。","ئۇ قارشى تەرەپنىڭ خاتالىقىنى ئوچۇق ئەيىبلىدى.","u qarshi terepning xataliqini ochuq eyiblidi."]],"兵营":[["兵营里训练着年轻的士兵。","ھەربىي لاگېردا ياش ئەسكەرلەر تەربىيىلىنىۋاتىدۇ.","herbiy lagérda yash eskerler terbiyiliniwatidu."]],"冤头":[["冤头债主终会找来。","ئەپسۇسلىكنىڭ باشلىنىشى ۋە قەرزدارى ئاخىرىدا كېلىپ چىقىدۇ.","epsuslikning bashlinishi we qerzdari axirida kélip chiqidu."]],"冰刀":[["冰刀是滑冰运动员的重要装备。","تەبىرەن تېخنىكىسى پىششىق تەييارلانغان.","tebiren téxnikisi pishshiq teyyarlanghan."]],"冰墩墩":[["冰墩墩是冬奥会的吉祥物。","بىڭ دۈندۈن قىشكى ئولىمپىك ئويۇنلىرىنىڭ بەختلىك بەلگىسى.","bing dündün qishki olimpik oyunlirining bextlik belgisi."]],"前臼齿":[["前臼齿用于咀嚼。","ئالدىنقى ئەزىي چىش چايناشقا ئىشلىتىلىدۇ.","aldinqi eziy chish chaynashqa ishlitilidu."]],"前咽":[["前咽部位容易发炎。","ئالدىنقى ھالقىما ئورنى ئاسان ياللۇغلىنىدۇ.","aldinqi halqima orni asan yallughlinidu."]],"前奏曲":[["前奏曲为乐曲铺垫。","ئالدىنقى مۇقەددىمە مۇزىكىغا ئاساس سالىدۇ.","aldinqi muqeddime muzikigha asas salidu."]],"剔除":[["老师从名单中剔除了不符合条件的人。","ئوقۇتقۇچى تىزىملىكتىن شەرتكە ئۇيغۇن كەلمەيدىغانلارنى چىقىرىۋەتتى.","oqutquchi tizimliktin shertke uyghun kelmeydighanlarni chiqiriwetti."]],"副州长":[["副州长代理州长职务期间表现优异。","مۇئاۋىن ئوبلاست باشلىقى ئوبلاست باشلىقى ۋەزىپىسىنى ۋاكالەتەن ئۆتىگەن مەزگىلدە ئالاھىدە نەتىجە كۆرسەتتى.","muawin oblast bashliqi oblast bashliqi wezipisini wakaleten ötigen mezgilde alahide netije körsetti."]],"副食":[["副食是搭配主食食用的食物。","قوشۇمچە يېمەكلىك ئاساسلىق يېمەكلىك بىلەن بىرگە ئىستېمال قىلىنىدىغان يېمەكلىكتۇر.","qoshumche yémeklik asasliq yémeklik bilen birge istémal qilinidighan yémekliktur."]],"刘表":[["刘表是东汉末年的一位军阀。","لىۇ بياۋ شەرقىي خەن دەۋرىنىڭ ئاخىرىدىكى بىر ھەربىي باشلىق.","liu byaw sherqiy xen dewrining axiridiki bir herbiy bashliq."]],"加冰":[["请给这杯饮料加冰。","بۇ ئىچىملىككە مۇز قوشۇڭ.","bu ichimlikke muz qoshung."]],"勒索":[["他遭到黑帮勒索。","ئۇ قارا ئېغىزلىق گۇرۇھنىڭ تەھدىتىگە ئۇچرىدى.","u qara éghizliq guruhning tehditige uchridi."]],"勤朴":[["公司倡导勤朴作风，节约资源。","شىركەت ئىقتىسادچىل ۋە ساددە ئىستىلنى تەشەببۇس قىلىپ، بايلىقنى تېجەيدۇ.","shirket iqtisadchil we sadde istilni teshebbus qilip, bayliqni téjeydu."]],"劝服":[["他用道理成功劝服了对方。","ئۇ مۇنازىرە ئارقىلىق قارشى تەرەپنى ئۇتۇقلۇق قايىل قىلدى.","u munazire arqiliq qarshi terepni utuqluq qayil qildi."]],"北半球":[["北半球夏季气候炎热。","شىمالىي يېرىم شارنىڭ ياز پەسلىدە ھاۋاسى ئىسسىق.","shimaliy yérim sharning yaz peslide hawasi issiq."]],"汇价":[["今天的汇价有所波动。","بۈگۈنكى پۇل ئالماشتۇرۇش نىسبىتىدە تەۋرىنىش بار.","bügünki pul almashturush nisbitide tewrinish bar."]],"千阳":[["千阳地区风景优美。","چىيەنياڭ رايونىنىڭ مەنزىرىسى گۈزەل.","chiyenyang rayonining menzirisi güzel."]],"千奇百怪":[["这里的风景千奇百怪。","بۇ يەرنىڭ مەنزىرىسى مىڭ خىل غەلىتە.","bu yerning menzirisi ming xil ghelite."]],"千挑万选":[["经过千挑万选，终于找到。","مىڭ تاللاش، مىڭ ئىزدىنىشتىن كېيىن ئاخىرى تېپىلدى.","ming tallash, ming izdinishtin kéyin axiri tépildi."]],"半吊子":[["他学东西总是半吊子，不深入。","ئۇ بىرەر نەرسە ئۆگەنگەندە ھەمىشە يېرىم-يېرىم قىلىپ، چوڭقۇرلاشتۇرمايدۇ.","u birer nerse ögengende hemishe yérim-yérim qilip, chongqurlashturmaydu."]],"北镇":[["北镇历史悠久，文化深厚。","شىمالىي بازار ئۇزۇن تارىخقا ۋە چوڭقۇر مەدەنىيەتكە ئىگە.","shimaliy bazar uzun tarixqa we chongqur medeniyetke ige."]],"北马里亚纳":[["北马里亚纳是美国的海外领地。","شىمالىي مارىيانا ئامېرىكىنىڭ چەت ئەل زېمىنى.","shimaliy mariyana amérikining chet el zémini."]],"南半球":[["南半球冬季寒冷。","جەنۇبىي يېرىم شارنىڭ قىشى سوغۇق.","jenubiy yérim sharning qishi soghuq."]],"升号":[["音乐中的升号表示音高升高。","مۇزىكىدىكى دىئېز ئىشارىسى ئاۋاز ئېگىزلىكىنىڭ كۆتۈرۈلگەنلىكىنى بىلدۈرىدۇ.","muzikidiki diéz isharisi awaz égizlikining kötürülgenlikini bildüridu."]],"升起":[["太阳从东方缓缓升起。","قۇياش شەرقتىن ئاستا كۆتۈرۈلىدۇ.","quyash sherqtin asta kötürülidu."]],"千米":[["马拉松的标准赛程是42.195千米。","مارافوننىڭ ئۆلچەملىك مۇساپىسى 42.195 كىلومېتىر.","marafonning ölchemlik musapisi 42.195 kilométir."]],"北山羊":[["北山羊是一种生活在山区的哺乳动物。","بېيشان تېكىسى تاغلىق رايونلاردا ياشايدىغان بىر سۈت ئەمگۈچى ھايۋاندۇر.","béyshan tékisi taghliq rayonlarda yashaydighan bir süt emgüchi haywandur."]],"占星术":[["占星术在历史上曾被广泛使用。","مۇنەججىملىك تارىختا كەڭ كۆلەمدە ئىشلىتىلگەن.","munejjimlik tarixta keng kölemde ishlitilgen."]],"卡利多尼亚":[["卡利多尼亚拥有丰富的自然资源。","كالىدونىيە باي تەبىئىي بايلىققا ئىگە.","kalidoniye bay tebiiy bayliqqa ige."]],"厚古薄今":[["他厚古薄今。","ئۇ قەدىمكىنى قەدىرلەپ، ھازىرقىنى كەمسىتىدۇ.","u qedimkini qedirlep, hazirqini kemsitidu."]],"印支半岛":[["印支半岛地形复杂。","ھىندىچىن يېرىم ئارىلىنىڭ يەر شەكلى مۇرەككەپ.","hindichin yérim arilining yer shekli murekkep."]],"去火":[["这个药能去火。","بۇ دورا ئوتنى چۈشۈرەلەيدۇ.","bu dora otni chüshüreleydu."]],"卵母细胞":[["卵母细胞是未成熟的卵子。","تۇخۇم ئانىلىق ھۈجەيرىسى يېتىلمىگەن تۇخۇمدۇر.","tuxum aniliq hüjeyrisi yétilmigen tuxumdur."]],"南海子":[["南海子公园风景优美。","نەنھەيزى باغچىسىنىڭ مەنزىرىسى گۈزەل.","nenheyzi baghchisining menzirisi güzel."]],"受雇":[["他受雇于一家科技公司。","ئۇ بىر تېخنىكا شىركىتىدە ئىشلىگەن.","u bir téxnika shirkitide ishligen."]],"口水鸡":[["这道口水鸡味道鲜美。","بۇ ئېغىز توخۇسىنىڭ تەمى لەززەتلىك.","bu éghiz toxusining temi lezzetlik."]],"受过":[["他受过高等教育。","ئۇ ئالىي مائارىپ ئالغان.","u aliy maarip alghan."]],"口欲期":[["口欲期是儿童心理发展的阶段。","ئاغىز باسقۇچى بالىلارنىڭ پىسخىكىلىق تەرەققىيات باسقۇچىدۇر.","aghiz basquchi balilarning pisxikiliq tereqqiyat basquchidur."]],"取悦":[["他试图用幽默来取悦观众。","ئۇ تاماشىبىنلارنى خۇشال قىلىش ئۈچۈن يۇمۇر ئىشلىتىشكە تىرىشتى.","u tamashibinlarni xushal qilish üchün yumur ishlitishke tirishti."]],"古朴":[["古朴的乡村充满自然气息。","قەدىمىي ئۇسلۇبتىكى يېزا-كەنت تەبىئىي ھاۋا بىلەن تولغان.","qedimiy uslubtiki yéza-kent tebiiy hawa bilen tolghan."]],"古琴":[["她正在练习弹奏古琴的古典曲目。","ئۇ قەدىمكى چىڭ ئەسۋابىدا كلاسسىك كۈي چېلىشنى مەشىق قىلىۋاتىدۇ.","u qedimki ching eswabida klassik küy chélishni meshiq qiliwatidu."]],"古城区":[["古城区保留了许多传统建筑。","قەدىمكى شەھەر رايونى نۇرغۇن ئەنئەنىۋى بىنالارنى ساقلاپ قالغان.","qedimki sheher rayoni nurghun en'eniwi binalarni saqlap qalghan."]],"古巴":[["古巴是加勒比海的一个国家。","كۇبا كارىب دېڭىزىدىكى بىر دۆلەت.","kuba karib déngizidiki bir dölet."]],"史观":[["史观影响人们对历史事件的解读。","تارىخىي كۆز قاراش كىشىلەرنىڭ تارىخىي ۋەقەلەرنى چۈشەندۈرۈشىگە تەسىر كۆرسىتىدۇ.","tarixiy köz qarash kishilerning tarixiy weqelerni chüshendürüshige tesir körsitidu."]],"可选择丢弃":[["不需要的数据可选择丢弃。","ئېھتىياجسىز سانلىق مەلۇماتلارنى تاشلاشنى تاللىسا بولىدۇ.","éhtiyajsiz sanliq melumatlarni tashlashni tallisa bolidu."]],"可食":[["这种植物可食用。","بۇ خىل ئۆسۈملۈكنى يېگىلى بولىدۇ.","bu xil ösümlükni yégili bolidu."]],"句法":[["句法分析有助于理解句子的结构。","جۈملە قۇرۇلمىسى تەھلىلى جۈملىنىڭ قۇرۇلمىسىنى چۈشىنىشكە ياردەم بېرىدۇ.","jümle qurulmisi tehlili jümlining qurulmisini chüshinishke yardem béridu."]],"司空见惯":[["这种场景早已司空见惯。","بۇنداق مەنزىرە ئاللىبۇرۇن كۆنۈملۈك بولۇپ قالغان.","bundaq menzire alliburun könümlük bolup qalghan."]],"同义语":[["同义语丰富了语言表达。","مەنىداش سۆزلەر تىل ئىپادىسىنى بېيىتىدۇ.","menidash sözler til ipadisini béyitidu."]],"同舟共济":[["大家同舟共济，渡过难关。","كۆپچىلىك بىر كېمىدە بولۇپ، قىيىنچىلىقنى يېڭىپ ئۆتتى.","köpchilik bir kémide bolup, qiyinchiliqni yéngip ötti."]],"同性恋":[["同性恋群体需要更多理解。","ئوخشاش جىنسلىقلارغا ئامراقلىق گۇرۇپپىسى تېخىمۇ كۆپ چۈشىنىشنى تەلەپ قىلىدۇ.","oxshash jinsliqlargha amraqliq guruppisi téximu köp chüshinishni telep qilidu."]],"吟咏":[["他吟咏着优美的诗篇。","ئۇ گۈزەل شېئىرلارنى ئوقۇپ ئاۋازلاندۇردى.","u güzel shéirlarni oqup awazlandurdi."]],"吡唑":[["吡唑常用于药物合成。","پىرازول دورا سىنتېزىدا كۆپ ئىشلىتىلىدۇ.","pirazol dora sintézida köp ishlitilidu."]],"否极泰来":[["否极泰来，苦尽甘来。","ياخشىلىق چېكىگە يەتكەندە يامانلىق كېلىدۇ، ئاچچىق تۈگىگەندە تاتلىق كېلىدۇ.","yaxshiliq chékige yetkende yamanliq kélidu, achchiq tügigende tatliq kélidu."]],"吱吱声":[["老鼠发出吱吱声。","چاشقان چىق-چىق قىلىپ ئاۋاز چىقاردى.","chashqan chiq-chiq qilip awaz chiqardi."]],"吹球机":[["吹球机让乒乓球快速旋转。","شار پۈۋلەيدىغان ماشىنا تەننەس توپىنى تېز ئايلاندۇرىدۇ.","shar püwleydighan mashina tennes topini téz aylanduridu."]],"周游":[["他喜欢周游。","ئۇ ئايلىنىپ سەيلە قىلىشنى ياخشى كۆرىدۇ.","u aylinip seyle qilishni yaxshi köridu."]],"和胃力气":[["这道菜能和胃力气。","بۇ تائام ئاشقازاننى كۈچلەندۈرەلەيدۇ.","bu taam ashqazanni küchlendüreleydu."]],"哈奴曼":[["哈奴曼是印度神话中的英雄。","خانۇمان ھىندىستان ئەپسانىسىدىكى قەھرىماندۇر.","xanuman hindistan epsanisidiki qehrimandur."]],"呵斥":[["老师呵斥了不遵守纪律的学生。","ئوقۇتقۇچى تەرتىپكە بويسۇنمىغان ئوقۇغۇچىنى ئەيىبلىدى.","oqutquchi tertipke boysunmighan oqughuchini eyiblidi."]],"呋喃西林":[["呋喃西林是一种常用的消毒剂。","فۇرانسىلىن كۆپ ئىشلىتىلىدىغان بىر خىل دېزىنفېكسىيە دورىسىدۇر.","furansilin köp ishlitilidighan bir xil dézinféksiye dorisidur."]],"品脱":[["他买了一品脱鲜牛奶，准备做早餐。","ئۇ بىر پىنت سۈت سېتىۋېلىپ، ئەتىگەنلىك تاماق تەييارلىماقچى بولدى.","u bir pint süt sétiwélip, etigenlik tamaq teyyarlimaqchi boldi."]],"咣当":[["门咣当一声关上了。","ئىشىك گۈلدۈرلەپ يېپىلدى.","ishik güldürlep yépildi."]],"咬甲癖":[["她患有咬甲癖，经常无意识地咬指甲。","ئۇ تىرناق چىشلەش كېسىلىگە گىرىپتار بولۇپ، كۆپىنچە بىلگەنسىز ھالدا تىرنىقىنى چىشلەيدۇ.","u tirnaq chishlesh késilige giriptar bolup, köpinche bilgensiz halda tirniqini chishleydu."]],"唐德宗":[["唐德宗在位期间面临诸多内忧外患。","تاڭ دېزۇڭ ھۆكۈمرانلىق قىلغان مەزگىلدە نۇرغۇن ئىچكى ۋە تاشقى مەسىلىلەرگە دۇچ كەلگەن.","tang dézung hökümranliq qilghan mezgilde nurghun ichki we tashqi mesililerge duch kelgen."]],"丧志":[["他因失败而丧志，一蹶不振。","ئۇ مەغلۇبىيەت سەۋەبىدىن روھى چۈشۈپ، ھېچ ئىشقا يارىمايدىغان بولۇپ قالدى.","u meghlubiyet sewebidin rohi chüshüp, héch ishqa yarimaydighan bolup qaldi."]],"唤头":[["他唤头呼脑地指挥着。","ئۇ باش-ئاخىرىنى بىلمەي بۇيرۇق چۈشۈرۈپ تۇردى.","u bash-axirini bilmey buyruq chüshürüp turdi."]],"嘴巴子":[["他挨了一个嘴巴子。","ئۇ بىر شاپىلاق يەدى.","u bir shapilaq yedi."]],"咝咝声":[["锅里的水发出咝咝声。","قازاندىكى سۇ شىشىلداپ ئاۋاز چىقاردى.","qazandiki su shishildap awaz chiqardi."]],"噪大苇莺":[["噪大苇莺是一种生活在湿地中的鸟类。","شاۋقۇنلۇق قومۇش چىمچىقى سۇلۇق يەرلەردە ياشايدىغان قۇش تۈرىدۇر.","shawqunluq qomush chimchiqi suluq yerlerde yashaydighan qush türidur."]],"噶隆":[["噶隆是一种古老的舞蹈形式。","گالۇڭ قەدىمىي بىر ئۇسسۇل شەكلى.","galung qedimiy bir ussul shekli."]],"哗儿哗儿":[["河水哗儿哗儿地流着。","دەريا سۈيى شىلدىرلاپ ئاقماقتا.","derya süyi shildirlap aqmaqta."]],"四月份":[["四月份天气逐渐转热。","تۆتىنچى ئايدا ھاۋا تەدرىجىي ئىسسىيدۇ.","tötinchi ayda hawa tedrijiy issiydu."]],"回邮信封":[["使用回邮信封寄信。","قايتۇرما ئېلخەت كونۋېرتى ئىشلىتىپ خەت ئەۋەتىڭ.","qayturma élxet konwérti ishlitip xet eweting."]],"因人而异":[["方法需因人而异，灵活调整。","ئۇسۇل كىشىگە قاراپ پەرقلىنىشى، جانلىق تەڭشىلىشى كېرەك.","usul kishige qarap perqlinishi, janliq tengshilishi kérek."]],"因数":[["这个结果的主要因数是什么？","بۇ نەتىجىنىڭ ئاساسلىق كۆپەيتكۈچى نېمە؟","bu netijining asasliq köpeytküchi néme?"]],"国中":[["国中时期是最难忘的回忆。","دۆلەت ئوتتۇرا مەكتەپ دەۋرى ئەڭ ئۇنتۇلغۇسىز ئەسلىمىدۇر.","dölet ottura mektep dewri eng untulghusiz eslimidur."]],"国家地震局":[["国家地震局监测全国的地震活动。","دۆلەت يەر تەۋرەش ئىدارىسى پۈتۈن مەملىكەتتىكى يەر تەۋرەش پائالىيىتىنى كۆزىتىدۇ.","dölet yer tewresh idarisi pütün memlikettiki yer tewresh paaliyitini közitidu."]],"国家重点学科":[["该学科被列为国家重点学科。","بۇ پەن دۆلەت نۇقتىلىق پەن تۈرى قىلىپ بەلگىلەندى.","bu pen dölet nuqtiliq pen türi qilip belgilendi."]],"国大党":[["国大党是印度主要的政治力量。","دۆلەت چوڭ پارتىيەسى ھىندىستاننىڭ ئاساسلىق سىياسىي كۈچى.","dölet chong partiyesi hindistanning asasliq siyasiy küchi."]],"固安县":[["固安县位于河北省中部地区。","گۇئەن ناھىيىسى خېبېي ئۆلكىسىنىڭ مەركىزىي رايونىدا جايلاشقان.","guen nahiyisi xébéy ölkisining merkiziy rayonida jaylashqan."]],"国家安全部":[["国家安全部制定安全相关法规。","دۆلەت بىخەتەرلىك مىنىستىرلىقى بىخەتەرلىككە ئائىت تۈزۈملەرنى تۈزىدۇ.","dölet bixeterlik ministirliqi bixeterlikke ait tüzümlerni tüzidu."]],"国家政策":[["国家政策引导社会的发展方向。","دۆلەت سىياسىتى جەمئىيەتنىڭ تەرەققىيات يۆنىلىشىنى يېتەكلەيدۇ.","dölet siyasiti jem'iyetning tereqqiyat yönilishini yétekleydu."]],"国际金融公司":[["国际金融公司支持发展中国家项目。","خەلقئارا مالىيە شىركىتى تەرەققىي قىلىۋاتقان دۆلەتلەرنىڭ تۈرلىرىنى قوللايدۇ.","xelq'ara maliye shirkiti tereqqiy qiliwatqan döletlerning türlirini qollaydu."]],"国际关系":[["国际关系影响国家间的合作。","خەلقئارا مۇناسىۋەتلەر دۆلەتلەر ئارا ھەمكارلىققا تەسىر كۆرسىتىدۇ.","xelq'ara munasiwetler döletler ara hemkarliqqa tesir körsitidu."]],"土族":[["土族有自己的文化。","تۇ مىللىتىنىڭ ئۆز مەدەنىيىتى بار.","tu millitining öz medeniyiti bar."]],"国际人权标准":[["这些国际人权标准适用于所有国家。","بۇ خەلقئارا ئىنسان ھوقۇقى ئۆلچەملىرى بارلىق دۆلەتلەرگە قوللىنىلىدۇ.","bu xelq'ara insan hoquqi ölchemliri barliq döletlerge qollinilidu."]],"土到不行":[["他的打扮土到不行。","ئۇنىڭ كىيىنىشى توپىلىقتىن ئاشىپ كەتتى.","uning kiyinishi topiliqtin aship ketti."]],"地理纬度":[["地理纬度用来确定地理位置。","جۇغراپىيەلىك كەڭلىك جۇغراپىيەلىك ئورۇننى بەلگىلەشكە ئىشلىتىلىدۇ.","jughrapiyelik kenglik jughrapiyelik orunni belgileshke ishlitilidu."]],"地面层":[["地面层是土壤最表层的部分。","يەر يۈزى قەۋىتى تۇپراقنىڭ ئەڭ ئۈستى قەۋىتىدۇر.","yer yüzi qewiti tupraqning eng üsti qewitidur."]],"埤头":[["埤头是古代的一种堤坝。","پىتۇ قەدىمكى دەۋرلەردىكى بىر خىل توغان ئىدى.","pitu qedimki dewrlerdiki bir xil toghan idi."]],"执拗":[["孩子性格有些执拗。","بالىنىڭ خاراكتېرى بىر قەدەر قەيسەر.","balining xaraktéri bir qeder qeyser."]],"地理学":[["地理学是研究地球特征的科学。","گېئوگرافىيە يەر شارىنىڭ ئالاھىدىلىكلىرىنى تەتقىق قىلىدىغان پەن.","géografiye yer sharining alahidiliklirini tetqiq qilidighan pen."]],"垂青":[["他的才华得到了导师的垂青。","ئۇنىڭ تالانتى ئۇستازىنىڭ دىققىتىنى تارتقان.","uning talanti ustazining diqqitini tartqan."]],"基督教":[["基督教是世界三大宗教之一。","خىرىستىيان دىنى دۇنيادىكى ئۈچ چوڭ دىننىڭ بىرىدۇر.","xiristiyan dini dunyadiki üch chong dinning biridur."]],"坚壁清野":[["军队采用坚壁清野的战术。","ئارمىيە جىيەنبى-چىڭيە تاكتىكىسىنى قوللاندى.","armiye jiyenbi-chingye taktikisini qollandi."]],"塑封":[["文件经过塑封处理。","ھۆججەت پلاستىك پىچەت بىلەن بىر تەرەپ قىلىندى.","höjjet plastik pichet bilen bir terep qilindi."]],"塞拉耶佛":[["塞拉耶佛是波斯尼亚和黑塞哥维那的首都。","سارايېۋو بوسنىيە ۋە ھېرسېگوۋىنانىڭ پايتەختى.","sarayéwo bosniye we hérségowinaning paytexti."]],"墨西哥湾":[["墨西哥湾是重要的石油产区。","مېكسىكا قولتۇقى مۇھىم نېفىت ئىشلەپچىقىرىش رايونى.","méksika qoltuqi muhim néfit ishlepchiqirish rayoni."]],"坠饰":[["项链上的坠饰闪闪发光。","مونچاقنىڭ زىننەت تاشلىرى يالتىراپ تۇرىدۇ.","monchaqning zinnet tashliri yaltirap turidu."]],"壁橱":[["壁橱里存放着换季的衣服。","تام شكاپىدا پەسىل ئالمىشىدىغان كىيىملەر ساقلىنىدۇ.","tam shkapida pesil almishidighan kiyimler saqlinidu."]],"壁虱":[["壁虱可能会引起皮肤瘙痒。","تام كەنىسى تېرىنى قىچىشىشقا سەۋەب بولۇشى مۇمكىن.","tam kenisi térini qichishishqa seweb bolushi mumkin."]],"报单":[["请报单时详细说明商品状况。","مال دوكلاتى بەرگەندە مەھسۇلات ئەھۋالىنى تەپسىلىي چۈشەندۈرۈڭ.","mal doklati bergende mehsulat ehwalini tepsiliy chüshendürüng."]],"报幕":[["报幕员宣布了下一场演出内容。","ئېلانچى كېيىنكى مەيدان نومۇرنىڭ مەزمۇنىنى ئېلان قىلدى.","élanchi kéyinki meydan nomurning mezmunini élan qildi."]],"夏县":[["夏县位于山西省的西南部。","شىيا ناھىيىسى شەنشى ئۆلكىسىنىڭ جەنۇبىي غەربىگە جايلاشقان.","shiya nahiyisi shenshi ölkisining jenubiy gherbige jaylashqan."]],"多个":[["他买了多个礼物。","ئۇ كۆپ سوۋغات سېتىۋالدى.","u köp sowghat sétiwaldi."]],"多项式":[["多项式是由多个项组成的代数表达式。","كۆپ ئەزالىق ئىپادە كۆپ ئەزادىن تەركىب تاپقان ئالگېبرالىق ئىپادىدۇر.","köp ezaliq ipade köp ezadin terkib tapqan algébraliq ipadidur."]],"大合唱":[["大家一起参加大合唱。","ھەممەيلەن بىرلىكتە چوڭ خور ئوقۇشىغا قاتناشتى.","hemmeylen birlikte chong xor oqushigha qatnashti."]],"大化县":[["大化县以丰富的矿产资源闻名。","داھۇا ناھىيىسى باي مىنېرال بايلىقلىرى بىلەن داڭلىق.","dahua nahiyisi bay minéral bayliqliri bilen dangliq."]],"夜间部":[["夜间部负责处理深夜的紧急事务。","كېچىلىك بۆلۈم چوڭقۇر كېچىدىكى جىددىي ئىشلارنى بىر تەرەپ قىلىشقا مەسئۇل.","kéchilik bölüm chongqur kéchidiki jiddiy ishlarni bir terep qilishqa mes'ul."]],"大汗":[["运动后他出了一身大汗。","تەنتەربىيەدىن كېيىن ئۇ بىر ئەۋجىگەچە تەرلىدى.","tenterbiyedin kéyin u bir ewjigeche terlidi."]],"大红鼻子":[["他有个大红鼻子，特别显眼。","ئۇنىڭ چوڭ قىزىل بۇرنى بار، ئىنتايىن كۆزگە چېلىقىدۇ.","uning chong qizil burni bar, intayin közge chéliqidu."]],"大西庇阿":[["大西庇阿是古希腊人。","سكىپىئو ئافرىقىلىق قەدىمكى گرېكلەردىن ئىدى.","skipio afriqiliq qedimki gréklerdin idi."]],"大西洋中脊":[["大西洋中脊贯穿整个大洋。","ئاتلانتىك ئوكيان ئوتتۇرا تاغ تىزمىسى پۈتۈن ئوكياننى كېسىپ ئۆتىدۇ.","atlantik okyan ottura tagh tizmisi pütün okyanni késip ötidu."]],"大脑死亡":[["医生宣布他大脑死亡。","دوختۇر ئۇنىڭ مېڭىسى ئۆلگەنلىكىنى ئېلان قىلدى.","doxtur uning méngisi ölgenlikini élan qildi."]],"天仙":[["天仙是神话中美丽而神圣的存在。","پەرىشتە ئەپسانىلەردىكى گۈزەل ۋە مۇقەددەس مەۋجۇدىيەت.","perishte epsanilerdiki güzel we muqeddes mewjudiyet."]],"天孙娘娘":[["天孙娘娘是中国神话中的女神。","تەڭرىنەۋرە خانىم جۇڭگو مىفولوگىيىسىدىكى بىر ئىلاھە ئىدى.","tengrinewre xanim junggo mifologiyisidiki bir ilahe idi."]],"太空探索":[["太空探索是人类追求未知的重要领域。","تەيكوڭنى ئىزدىنىش ئىنسانىيەتنىڭ نامەلۇمنى ئىزدىشىدىكى مۇھىم ساھە.","teykongni izdinish insaniyetning namelumni izdishidiki muhim sahe."]],"天河区":[["天河区是广州市的一个行政区。","تيەنخې رايونى گۇاڭجۇ شەھىرىنىڭ بىر مەمۇرىي رايونى.","tyenxé rayoni guangju shehirining bir memuriy rayoni."]],"天煞孤星":[["他被认为是天煞孤星。","ئۇ تيەنشا گۇۋاڭشىڭ دەپ قارىلىدۇ.","u tyensha guwangshing dep qarilidu."]],"失衡":[["身体失衡容易摔倒。","بەدەن تەڭپۇڭسىزلىقى ئاسانلا يىقىلىشقا سەۋەب بولىدۇ.","beden tengpungsizliqi asanla yiqilishqa seweb bolidu."]],"天候":[["天候变化影响农作物的生长。","ھاۋارايى ئۆزگىرىشى يېزا ئىگىلىك زىرائەتلىرىنىڭ ئۆسۈشىگە تەسىر كۆرسىتىدۇ.","hawarayi özgirishi yéza igilik ziraetlirining ösüshige tesir körsitidu."]],"天台宗":[["天台宗是中国佛教的重要宗派。","تيەنتەي مەزھىبى جۇڭگو بۇددا دىنىنىڭ مۇھىم مەزھىبلىرىنىڭ بىرىدۇر.","tyentey mezhibi junggo budda dinining muhim mezhiblirining biridur."]],"奉公守法":[["奉公守法是公民义务。","پۇقرالارنىڭ مەجبۇرىيىتى پۇقرالىق مەجبۇرىيىتىدۇر.","puqralarning mejburiyiti puqraliq mejburiyitidur."]],"套汇":[["套汇属于违法行为。","يۈرۈمچىلىك پۇل ئالماشتۇرۇش قانۇنغا خىلاپ قىلمىش.","yürümchilik pul almashturush qanungha xilap qilmish."]],"奸诈":[["那人奸诈狡猾。","ئۇ كىشى ئىنتايىن مەككار ۋە قىلمىش.","u kishi intayin mekkar we qilmish."]],"女娲氏":[["女娲氏创造了人类。","نۈۋا ئۇرۇقى ئىنسانىيەتنى ياراتتى.","nüwa uruqi insaniyetni yaratti."]],"奋武扬威":[["将军奋武扬威，震慑敌军。","گېنېرال ئۇرۇش ئىقتىدارىنى نامايان قىلىپ، دۈشمەن قوشۇنىنى ھودۇقتۇردى.","général urush iqtidarini namayan qilip, düshmen qoshunini hoduqturdi."]],"女佣":[["女佣辛勤地打扫房间。","ئايال خىزمەتچى ئۆينى تىرىشچانلىق بىلەن تازىلىدى.","ayal xizmetchi öyni tirishchanliq bilen tazilidi."]],"好男不跟女斗":[["好男不跟女斗，让一步吧。","جەسۇر ئەر ئايال بىلەن ئۇرۇشمايدۇ، بىر قەدەم يول قويۇڭ.","jesur er ayal bilen urushmaydu, bir qedem yol qoyung."]],"威士忌酒":[["这款威士忌酒很纯。","بۇ ۋىسكى ناھايىتى ساپ.","bu wiski nahayiti sap."]],"姚雪垠":[["姚雪垠创作了长篇小说《李自成》。","ياۋشۈيىن «لى زىچېڭ» ناملىق ئۇزۇن روماننى ئىجاد قىلغان.","yawshüyin «li zichéng» namliq uzun romanni ijad qilghan."]],"嫌猜":[["两人因嫌猜而冷战。","ئىككىيلەن گۇمان-شەك سەۋەبىدىن سوغۇق مۇناسىۋەتتە بولدى.","ikkiylen guman-shek sewebidin soghuq munasiwette boldi."]],"子鼠":[["子鼠是十二生肖中的第一位。","تارماق چاشقان ئون ئىككى ھايۋان يىلىنىڭ بىرىنچىسىدۇر.","tarmaq chashqan on ikki haywan yilining birinchisidur."]],"孑遗生物":[["孑遗生物是古老的物种。","يالغۇز قالدۇق جانلىق قەدىمكى تۈرلەردۇر.","yalghuz qalduq janliq qedimki türlerdur."]],"孤沙锥":[["孤沙锥是一种罕见的鸟类。","يالغۇز قۇم چىللىسى ئاز ئۇچرايدىغان قۇش تۈرىدۇر.","yalghuz qum chillisi az uchraydighan qush türidur."]],"孤独于世":[["他孤独于世，无人理解。","ئۇ دۇنيادا يالغۇز، ھېچكىم ئۇنى چۈشەنمەيدۇ.","u dunyada yalghuz, héchkim uni chüshenmeydu."]],"孝悌忠信":[["孝悌忠信是传统美德。","پىداكارلىق، ئاكا-ئىنىغا ھۆرمەت، ۋەپادارلىق ۋە ئىشەنچلىكلىك ئەنئەنىۋى ئەخلاق-پەزىلەتتۇر.","pidakarliq, aka-inigha hörmet, wepadarliq we ishenchliklik en'eniwi exlaq-pezilettur."]],"孝昌县":[["孝昌县风景优美，物产丰富。","شياۋچاڭ ناھىيىسىنىڭ مەنزىرىسى گۈزەل، مەھسۇلاتلىرى مول.","shyawchang nahiyisining menzirisi güzel, mehsulatliri mol."]],"孝服":[["穿孝服是表达哀思的方式。","پىداكارلىق كىيىمى كىيىش قايغۇ-ھەسرەتنى ئىپادىلەشنىڭ بىر ئۇسۇلىدۇر.","pidakarliq kiyimi kiyish qayghu-hesretni ipadileshning bir usulidur."]],"安培":[["安培是电流的国际单位。","ئامپېر توك كۈچىنىڭ خەلقئارالىق بىرلىكىدۇر.","ampér tok küchining xelq'araliq birlikidur."]],"宏愿":[["他立下宏愿，要改变世界。","ئۇ دۇنيانى ئۆزگەرتىش ئۈچۈن ئۇلۇغ ئارزۇ ئورناتتى.","u dunyani özgertish üchün ulugh arzu ornatti."]],"安养院":[["安养院为老年人提供照护服务。","ئامان-ئېسەنلىك ئۆيى ياشانغانلارغا باققۇچىلىق مۇلازىمىتى تەمىنلەيدۇ.","aman-ésenlik öyi yashanghanlargha baqquchiliq mulazimiti teminleydu."]],"安全港":[["这里被视为国际关系中的安全港。","بۇ يەر خەلقئارا مۇناسىۋەتلەردە بىخەتەر پاناھ دەپ قارىلىدۇ.","bu yer xelq'ara munasiwetlerde bixeter panah dep qarilidu."]],"安全灯":[["安全灯在停电时会自动亮起。","بىخەتەرلىك چىرىغى توك توختىغاندا ئاپتوماتىك يېنىدۇ.","bixeterlik chirighi tok toxtighanda aptomatik yénidu."]],"宣道":[["他虔诚地宣道，传播信仰。","ئۇ تەقۋادارلىق بىلەن ۋەز ئېيتىپ، ئېتىقادنى تارقاتتى.","u teqwadarliq bilen wez éytip, étiqadni tarqatti."]],"客串":[["他今天来公司客串一下。","ئۇ بۈگۈن شىركەتكە كېلىپ مېھمان بولۇپ كەتتى.","u bügün shirketke kélip méhman bolup ketti."]],"富商巨贾":[["富商巨贾们推动了商业的发展。","باي سودىگەرلەر سودىنىڭ تەرەققىياتىنى ئىلگىرى سۈرگەن.","bay sodigerler sodining tereqqiyatini ilgiri sürgen."]],"寝苫枕块":[["他寝苫枕块，生活简朴。","ئۇ ھەسىر-خارا ئۈستىدە يېتىپ، تاشنى ياستۇق قىلدى، تۇرمۇشى ئاددىي ئىدى.","u hesir-xara üstide yétip, tashni yastuq qildi, turmushi addiy idi."]],"宁洱":[["宁洱位于云南省南部。","نىڭئېر يۈننەن ئۆلكىسىنىڭ جەنۇبىدا جايلاشقان.","ning'ér yünnen ölkisining jenubida jaylashqan."]],"富兰克林":[["富兰克林是美国著名的科学家。","فرانكلىن ئامېرىكىنىڭ مەشھۇر ئالىمى.","franklin amérikining meshhur alimi."]],"富农":[["富农在农业改革中发挥了重要作用。","باي دېھقانلار يېزا ئىگىلىك ئىسلاھاتىدا مۇھىم رول ئوينىدى.","bay déhqanlar yéza igilik islahatida muhim rol oynidi."]],"宽大为怀":[["面对冲突，他选择了宽大为怀。","توقۇنۇشقا دۇچ كەلگەندە، ئۇ كەڭ قورساقلىقنى تاللىدى.","toqunushqa duch kelgende, u keng qorsaqliqni tallidi."]],"宝贝疙瘩":[["他是个十足的宝贝疙瘩。","ئۇ پۈتۈنلەي بىر ئەركە تاش.","u pütünley bir erke tash."]],"家常便饭":[["家常便饭最让人怀念。","ئادەتتىكى تاماق ئادەمنى ئەڭ كۆپ سېغىندۇرىدۇ.","adettiki tamaq ademni eng köp séghinduridu."]],"尊尚":[["尊尚表示推崇和尊重。","زۇنشاڭ ئالىيلىماق ۋە ھۆرمەتلەشنى بىلدۈرىدۇ.","zunshang aliylimaq we hörmetleshni bildüridu."]],"小便":[["他早上起来去小便。","ئۇ ئەتىگەندە تۇرۇپ سۈيدۈك چىقىرىشقا بارىدۇ.","u etigende turup süydük chiqirishqa baridu."]],"小便池":[["酒店的小便池设计得很现代。","مېھمانساراينىڭ سۈيدۈك چىقىرىش ئەسۋابى زامانىۋى لايىھەلەنگەن.","méhmansarayning süydük chiqirish eswabi zamaniwi layihelengen."]],"小腿":[["跑步时，小腿会感到酸痛。","يۈگۈرگەندە پۇت ئاغرىيدۇ.","yügürgende put aghriydu."]],"尸体袋":[["尸体袋用于运输和处理遗体。","جەسەت خالتىسى جەسەتنى توشۇش ۋە بىر تەرەپ قىلىشقا ئىشلىتىلىدۇ.","jeset xaltisi jesetni toshush we bir terep qilishqa ishlitilidu."]],"展翅":[["小鸟开始展翅飞翔。","كىچىك قۇش قانات قېقىپ ئۇچۇشقا باشلىدى.","kichik qush qanat qéqip uchushqa bashlidi."]],"山峡":[["山峡是两山之间的狭窄水道。","شەنشيا ئىككى تاغ ئارىسىدىكى تار سۇ يولى.","shenshya ikki tagh arisidiki tar su yoli."]],"局子":[["警察局的简称是局子。","ساقچىخانىنىڭ قىسقارتىلما ئاتىلىشى جۈزى.","saqchixanining qisqartilma atilishi jüzi."]],"山乡":[["山乡的风景格外宁静。","تاغ يېزىسىنىڭ مەنزىرىسى ئالاھىدە جىمجىت.","tagh yézisining menzirisi alahide jimjit."]],"山鸡":[["山鸡的肉质鲜美可口。","تاغ توخۇسىنىڭ گۆشى لەززەتلىك ۋە تەملىك.","tagh toxusining göshi lezzetlik we temlik."]],"山案座":[["山案座位于天球北部。","شاڭئەن يۇلتۇزلار تۈركۈمى ساما كۈمبىزىنىڭ شىمالىدا جايلاشقان.","shang'en yultuzlar türkümi sama kümbizining shimalida jaylashqan."]],"山梨醇":[["山梨醇是一种甜味剂。","شاڭلىچۇن تاتلىق تەم بەرگۈچى ماددىدۇر.","shanglichun tatliq tem bergüchi maddidur."]],"居民楼":[["居民楼里住着许多家庭。","ئاھالىلەر بىناسىدا نۇرغۇن ئائىلە ياشايدۇ.","ahaliler binasida nurghun aile yashaydu."]],"岩流圈":[["岩流圈是地壳中岩石流动的边界。","تاش ئېقىمچان قاتلام يەر پوستىدىكى تاشلارنىڭ ئېقىش چېگراسى.","tash éqimchan qatlam yer postidiki tashlarning éqish chégrasi."]],"崔萤":[["崔萤是一位年轻的作家。","چۇي يىڭ ياش بىر يازغۇچى.","chuy ying yash bir yazghuchi."]],"巴克特里亚":[["巴克特里亚曾是古国。","باختارىيە ئىلگىرى قەدىمكى دۆلەت ئىدى.","baxtariye ilgiri qedimki dölet idi."]],"布兰妮·斯皮尔斯":[["布兰妮·斯皮尔斯是一位流行巨星。","برىتنىي سپىيرس بىر مودا يۇلتۇزىدۇر.","britniy spiyrs bir moda yultuzidur."]],"巴布亚新几内亚":[["巴布亚新几内亚位于太平洋西南部。","پاپۇئا يېڭى گۋىنېيە تىنچ ئوكياننىڭ جەنۇبىي غەربىي قىسمىدا جايلاشقان.","papua yéngi gwinéye tinch okyanning jenubiy gherbiy qismida jaylashqan."]],"巴拉巴斯":[["巴拉巴斯是土耳其的一座城市。","بالاباس تۈركىيەنىڭ بىر شەھىرى.","balabas türkiyening bir shehiri."]],"巴拉马利波":[["巴拉马利波是非洲的一个国家。","بالامالىپو ئافرىقىدىكى بىر دۆلەت.","balamalipo afriqidiki bir dölet."]],"布隆伯格":[["布隆伯格是全球知名的亿万富翁。","بۇلومبېرگ دۇنياغا مەشھۇر مىلياردېردۇر.","bulombérg dunyagha meshhur milyardérdur."]],"巴克莱银行":[["巴克莱银行历史悠久。","باركلىي بانكىسىنىڭ ئۇزۇن تارىخى بار.","barkliy bankisining uzun tarixi bar."]],"师娘":[["师娘是师父的妻子。","ئۇستازنىڭ ئايالى ئۇستازنىڭ رەپىقىسىدۇر.","ustazning ayali ustazning repiqisidur."]],"师宗县":[["师宗县以茶叶闻名。","ئۇستاز مەكتىپى ناھىيىسى چاي بىلەن داڭلىق.","ustaz mektipi nahiyisi chay bilen dangliq."]],"带分数":[["这道题可以用带分数计算。","بۇ مەسىلىنى ئارىلاش سان بىلەن ھېسابلاشقا بولىدۇ.","bu mesilini arilash san bilen hésablashqa bolidu."]],"年资":[["年资反映了员工的工作年限。","يىللىق ئەمگەك ئۆمرى خىزمەتچىلەرنىڭ خىزمەت يىللىرىنى ئەكس ئەتتۈرىدۇ.","yilliq emgek ömri xizmetchilerning xizmet yillirini eks ettüridu."]],"府第":[["这座府第历史悠久，令人向往。","بۇ فۇدى ئۇزۇن تارىخقا ئىگە، كىشىنى ئىنتىلگۈدەك قىلىدۇ.","bu fudi uzun tarixqa ige, kishini intilgüdek qilidu."]],"厨司":[["厨司是古代掌管饮食的官员。","ئاشپەز ئەمەلدارى قەدىمدە يېمەك-ئىچمەكنى باشقۇرىدىغان ئەمەلدار ئىدى.","ashpez emeldari qedimde yémek-ichmekni bashquridighan emeldar idi."]],"广开言路":[["广开言路，集思广益。","سۆز ئېچىش يولىنى كەڭ ئېچىپ، ئاممىنىڭ پىكرىنى جەم قىلىش كېرەك.","söz échish yolini keng échip, ammining pikrini jem qilish kérek."]],"彼此彼此":[["彼此彼此，无需多言。","ئۆز-ئارا ئوخشاش، كۆپ سۆزلەشنىڭ ھاجىتى يوق.","öz-ara oxshash, köp sözleshning hajiti yoq."]],"后勤学":[["后勤学对战争至关重要。","كېيىنكى مەمۇرىيەت ئۇرۇشتا ئىنتايىن مۇھىم.","kéyinki memuriyet urushta intayin muhim."]],"形色":[["山水的形色随季节变化而不同。","تاغ-سۇلارنىڭ شەكىلى ۋە رەڭگى پەسىلگە ئەگىشىپ ئوخشىمايدۇ.","tagh-sularning shekili we renggi pesilge egiship oxshimaydu."]],"强迫性储物症":[["强迫性储物症影响日常生活。","مەجبۇرىيەت خاراكتېرلىك بۇيۇم توپلاش كېسىلى كۈندىلىك تۇرمۇشقا تەسىر كۆرسىتىدۇ.","mejburiyet xaraktérlik buyum toplash késili kündilik turmushqa tesir körsitidu."]],"从属":[["这个部门完全从属于上级机构。","بۇ تارماق پۈتۈنلەي يۇقىرى دەرىجىلىك ئورگانغا قاراشلىق.","bu tarmaq pütünley yuqiri derijilik organgha qarashliq."]],"从头到脚":[["从头到脚，他都穿着运动服。","باشتىن پۇتىغىچە، ئۇ ھەممىسى تەنتەربىيە كىيىمى كىيىپتى.","bashtin putighiche, u hemmisi tenterbiye kiyimi kiyipti."]],"心肌梗塞":[["心肌梗塞是严重的心血管疾病。","يۈرەك مۇسكۇلى ئىنفاركتى جىددىي يۈرەك-قان تومۇر كېسىلىدۇر.","yürek muskuli infarkti jiddiy yürek-qan tomur késilidur."]],"心音":[["医生仔细听了他的心音。","دوختۇر ئۇنىڭ يۈرەك ئاۋازىنى ئەستايىدىل ئاڭلىدى.","doxtur uning yürek awazini estayidil anglidi."]],"心怦怦跳":[["见到她时，我的心怦怦跳。","ئۇنى كۆرگەندە، مېنىڭ يۈرىكىم دۈپۈلدەپ سوقتى.","uni körgende, méning yürikim düpüldep soqti."]],"心想":[["他心想这次考试一定行。","ئۇ بۇ قېتىمقى ئىمتىھاندىن چوقۇم ئۆتىمەن دەپ ئويلىدى.","u bu qétimqi imtihandin choqum ötimen dep oylidi."]],"快筛":[["医生用快筛检测出他的感染情况。","دوختۇر تېز تەكشۈرۈش ئارقىلىق ئۇنىڭ يۇقۇملىنىش ئەھۋالىنى بايقىدى.","doxtur téz tekshürüsh arqiliq uning yuqumlinish ehwalini bayqidi."]],"念日":[["念日是指专门用于冥想的日子。","خىيال كۈنى ئالاھىدە مۇراجىئەت قىلىدىغان كۈننى كۆرسىتىدۇ.","xiyal küni alahide murajiet qilidighan künni körsitidu."]],"怦然":[["他听到消息时，心中怦然一惊。","ئۇ خەۋەرنى ئاڭلىغاندا، يۈرىكى تۇيۇقسىز دۈپۈلدەپ كەتتى.","u xewerni anglighanda, yüriki tuyuqsiz düpüldep ketti."]],"性格不合":[["他们因性格不合而最终分手。","ئۇلار خاراكتېرلىرى ماسلاشمىغانلىقى ئۈچۈن ئاخىرىدا ئايرىلىشتى.","ular xaraktérliri maslashmighanliqi üchün axirida ayrilishti."]],"德雷斯顿":[["德雷斯顿是德国的工业城市。","درېزدېن گېرمانىيەنىڭ سانائەت شەھىرى.","drézdén gérmaniyening sanaet shehiri."]],"徽语":[["徽语是安徽地区的方言。","خۇي تىلى ئەنخۇي رايونىنىڭ شېۋىسى.","xuy tili enxuy rayonining shéwisi."]],"恐怖分子":[["恐怖分子被警方逮捕。","تېررورىستلار ساقچىلار تەرىپىدىن قولغا ئېلىندى.","térroristlar saqchilar teripidin qolgha élindi."]],"恐惧症":[["恐惧症需要专业治疗。","فوبىيە كەسپىي داۋالاشنى تەلەپ قىلىدۇ.","fobiye kespiy dawalashni telep qilidu."]],"性变态":[["性变态可能涉及不正常的性偏好。","جىنسىي ئەخلاقسىزلىق نورمال بولمىغان جىنسىي مايىللىقنى ئۆز ئىچىگە ئېلىشى مۇمكىن.","jinsiy exlaqsizliq normal bolmighan jinsiy mayilliqni öz ichige élishi mumkin."]],"怯生":[["这个孩子怯生，见到陌生人就躲。","بۇ بالا يات كىشىلەردىن تارتىنىدۇ، يات كىشىنى كۆرسىلا يوشۇرۇنىدۇ.","bu bala yat kishilerdin tartinidu, yat kishini körsila yoshurunidu."]],"恭祝":[["恭祝各位新年快乐，万事如意！","ھەممىڭلارغا يېڭى يىل مۇبارەك، ھەممە ئىش ئوڭۇشلۇق بولسۇن!","hemminglargha yéngi yil mubarek, hemme ish ongushluq bolsun!"]],"恐龙妹":[["她自称是恐龙妹，性格活泼。","ئۇ ئۆزىنى دىنوزاۋر قىز دەپ ئاتايدۇ، خاراكتېرى جانلىق.","u özini dinozawr qiz dep ataydu, xaraktéri janliq."]],"惝恍":[["他惝恍之间，忘记了时间。","ئۇ ئالدىراپ-تېنەپ، ۋاقىتنى ئۇنتۇپ قالدى.","u aldirap-ténep, waqitni untup qaldi."]],"悔恨交加":[["他悔恨交加，内心痛苦不堪。","ئۇ پۇشايمان بىلەن ئازاب ئىچىدە قالدى.","u pushayman bilen azab ichide qaldi."]],"悖晦":[["他的言论充满悖晦，让人困惑不已。","ئۇنىڭ سۆزلىرى زىددىيەتلىك بولۇپ، كىشىنى گاڭگىرىتىدۇ.","uning sözliri ziddiyetlik bolup, kishini ganggiritidu."]],"惨祸":[["这场惨祸夺走了许多生命。","بۇ پاجىئە نۇرغۇن ھاياتلارنى ئېلىپ كەتتى.","bu pajie nurghun hayatlarni élip ketti."]],"凭票入场":[["必须凭票入场。","چوقۇم بېلەت بىلەن كىرىش كېرەك.","choqum bélet bilen kirish kérek."]],"怄气":[["两人因为小事怄气半天。","ئىككىيلەن كىچىك ئىش سەۋەبىدىن يېرىم كۈن ئاچچىقلىشىپ قالدى.","ikkiylen kichik ish sewebidin yérim kün achchiqliship qaldi."]],"悭吝":[["悭吝的人往往不受欢迎。","بېخىل كىشىلەر كۆپىنچە ئاممىباب بولمايدۇ.","béxil kishiler köpinche ammibab bolmaydu."]],"感受器":[["皮肤上的感受器能感知外界刺激。","تېرىدىكى سەزگۈ ئورگانلىرى سىرتقى غىدىقلاشلارنى ھېس قىلالايدۇ.","téridiki sezgü organliri sirtqi ghidiqlashlarni hés qilalaydu."]],"成因":[["事故的成因仍在调查。","ھادىسىنىڭ سەۋەبى يەنىلا تەكشۈرۈلمەكتە.","hadisining sewebi yenila tekshürülmekte."]],"凭依":[["她感到孤独时，常常向朋友倾诉，寻求情感上的凭依。","ئۇ يالغۇزلىقنى ھېس قىلغاندا، كۆپىنچە دوستلىرىغا ئىچىنى ئېچىپ، ھېسسىيات جەھەتتىن تايىنىچ ئىزدەيدۇ.","u yalghuzliqni hés qilghanda, köpinche dostlirigha ichini échip, héssiyat jehettin tayinich izdeydu."]],"戏仿":[["这部作品对经典进行了戏仿。","بۇ ئەسەر كلاسسىك ئەسەرگە يوشۇرۇن تەقلىد قىلغان.","bu eser klassik eserge yoshurun teqlid qilghan."]],"戈壁滩":[["戈壁滩上生长着独特的植物。","گوبى چۆلىدە ئۆزگىچە ئۆسۈملۈكلەر ئۆسىدۇ.","gobi chölide özgiche ösümlükler ösidu."]],"戈壁荒滩":[["戈壁荒滩曾是游牧民族的家园。","گوبى قاقاس چۆلى ئىلگىرى كۆچمەنلەرنىڭ ماكانى ئىدى.","gobi qaqas chöli ilgiri köchmenlerning makani idi."]],"恋母情结":[["他表现出明显的恋母情结。","ئۇ ئېنىق ئانا-بالا مۇھەببىتى كۆڭۈل باغلىشىنى نامايان قىلدى.","u éniq ana-bala muhebbiti köngül baghlishini namayan qildi."]],"打千":[["他打千请了假。","ئۇ رۇخسەت سوراپ دەم ئالدى.","u ruxset sorap dem aldi."]],"打呃":[["他不停地打呃。","ئۇ توختىماي ئىككىلەيدۇ.","u toxtimay ikkileydu."]],"手活":[["他的手活很灵巧，能做出好作品。","ئۇنىڭ قول ھۈنەرى ئىنتايىن ماھىر، ياخشى ئەسەرلەرنى ياساپ چىقالايدۇ.","uning qol hüneri intayin mahir, yaxshi eserlerni yasap chiqalaydu."]],"打球":[["放学后他们一起去打球。","مەكتەپتىن قايتقاندىن كېيىن ئۇلار بىرلىكتە توپ ئوينايدۇ.","mekteptin qaytqandin kéyin ular birlikte top oynaydu."]],"打蛋器":[["用打蛋器搅打鸡蛋更均匀。","تۇخۇم قېقىدىغان ئۈسكۈنە بىلەن تۇخۇمنى ئارىلاشتۇرغاندا تېخىمۇ تەكشى بولىدۇ.","tuxum qéqidighan üsküne bilen tuxumni arilashturghanda téximu tekshi bolidu."]],"打铃":[["上课前，老师准时打铃。","دەرس باشلىنىشتىن بۇرۇن، ئوقۇتقۇچى ۋاقتىدا قوڭغۇراق چالىدۇ.","ders bashlinishtin burun, oqutquchi waqtida qongghuraq chalidu."]],"拉匝禄":[["拉匝禄是一位著名的音乐家。","لازارو مەشھۇر بىر مۇزىكانت.","lazaro meshhur bir muzikant."]],"抗震":[["这座建筑采用了先进的抗震设计。","بۇ بىنا ئىلغار يەر تەۋرەشكە قارشى لايىھەنى قوللاندى.","bu bina ilghar yer tewreshke qarshi layiheni qollandi."]],"找赎":[["他拿着旧钞票去银行找赎新钞。","ئۇ كونا پۇلنى بانكىغا ئېلىپ بېرىپ يېڭى پۇل ئالماشتۇردى.","u kona pulni bankigha élip bérip yéngi pul almashturdi."]],"拉法格":[["拉法格是法国著名的哲学家。","لافارگ فرانسىيەنىڭ مەشھۇر پەلسەپىچىسى.","lafarg fransiyening meshhur pelsepichisi."]],"拉狄克":[["拉狄克是一位物理学家。","رادىك بىر فىزىكا ئالىمى.","radik bir fizika alimi."]],"拘票":[["拘票上写明事由。","قاماق ھۆججىتىدە ئىشنىڭ سەۋەبى يېزىلغان.","qamaq höjjitide ishning sewebi yézilghan."]],"拘谨":[["她说话时显得拘谨。","ئۇ سۆزلىگەندە بىر ئاز تارتىنچاقلىق كۆرسەتتى.","u sözligende bir az tartinchaqliq körsetti."]],"拼桌":[["餐厅允许顾客拼桌用餐。","رېستوران خېرىدارلارنىڭ ئۈستەل بىرلەشتۈرۈپ تاماق يېيىشىگە رۇخسەت قىلىدۇ.","réstoran xéridarlarning üstel birleshtürüp tamaq yéyishige ruxset qilidu."]],"指导者":[["指导者提供专业建议。","يېتەكچى مۇتەخەسسىسلىك تەۋسىيەسى بېرىدۇ.","yétekchi mutexessislik tewsiyesi béridu."]],"舍命":[["他舍命救出了被困的群众。","ئۇ جانىنى خەتەرگە تىكىپ قىستىلىپ قالغان ئاممىنى قۇتقۇزۇپ چىقتى.","u janini xeterge tikip qistilip qalghan ammini qutquzup chiqti."]],"排面":[["这桌菜真有排面。","بۇ داستىخاندىكى تائاملارنىڭ ھەيۋىسى بار.","bu dastixandiki taamlarning heywisi bar."]],"掰开":[["他用力掰开瓶盖。","ئۇ بوتۇلكا قاپقىقىنى كۈچ بىلەن ئېچىۋەتتى.","u botulka qapqiqini küch bilen échiwetti."]],"推来推去":[["他把责任推来推去，不肯承担。","ئۇ مەسئۇلىيەتنى ئىتتىرىپ-تەرتىپ، ئۈستىگە ئېلىشقا ئۇنىمىدى.","u mes'uliyetni ittirip-tertip, üstige élishqa unimidi."]],"推卸":[["他试图推卸自己犯下的错误。","ئۇ ئۆزى قىلغان خاتالىقنى ئىتتىرىپ تاشلاشقا ئۇرۇندى.","u özi qilghan xataliqni ittirip tashlashqa urundi."]],"提示付款":[["系统提示付款即将到期。","سىستېما پۇل تۆلەش مۇددىتىنىڭ يېقىنلاشقانلىقىنى ئەسكەرتىدۇ.","sistéma pul tölesh mudditining yéqinlashqanliqini eskertidu."]],"扬州市":[["扬州市以园林和美食闻名全国。","ياڭجوۋ شەھىرى باغ-بوستانلىقلىرى ۋە تائاملىرى بىلەن پۈتۈن مەملىكەتكە داڭلىق.","yangjow shehiri bagh-bostanliqliri we taamliri bilen pütün memliketke dangliq."]],"换防":[["部队正在进行换防交接。","قىسىم ئالماشتۇرۇش تاپشۇرۇش-قوبۇل قىلىش ئېلىپ بېرىلماقتا.","qisim almashturush tapshurush-qobul qilish élip bérilmaqta."]],"挖苦":[["他经常用挖苦的话讽刺我。","ئۇ كۆپىنچە ئاچچىق سۆزلەر بىلەن مېنى مازاق قىلىدۇ.","u köpinche achchiq sözler bilen méni mazaq qilidu."]],"揭东县":[["揭东县位于广东省。","جېيدۇڭ ناھىيەسى گۇاڭدۇڭ ئۆلكىسىدە جايلاشقان.","jéydung nahiyesi guangdung ölkiside jaylashqan."]],"抢亲":[["古代有抢亲的习俗，以促成婚姻。","قەدىمكى زاماندا قىز تارتىۋېلىش ئادەتى بار بولۇپ، توي قىلىشقا ياردەم بېرەتتى.","qedimki zamanda qiz tartiwélish adeti bar bolup, toy qilishqa yardem béretti."]],"撂倒":[["他用力一推，把对手撂倒了。","ئۇ كۈچ بىلەن ئىتتىرىپ، رەقىبىنى يىقىتىۋەتتى.","u küch bilen ittirip, reqibini yiqitiwetti."]],"撇号":[["句子的结尾用撇号。","جۈملىنىڭ ئاخىرىغا ئايرىش بەلگىسى قويۇلىدۇ.","jümlining axirigha ayrish belgisi qoyulidu."]],"击弦类":[["这是击弦类乐器。","بۇ چەكلىك ساز ئەسۋابى.","bu cheklik saz eswabi."]],"摩拳擦掌":[["他摩拳擦掌，准备迎接挑战。","ئۇ مۇشتلىرىنى تۈگۈپ، خىرىسقا تاقابىل تۇرۇشقا تەييارلاندى.","u mushtlirini tügüp, xirisqa taqabil turushqa teyyarlandi."]],"擦边球":[["裁判判了个擦边球有效。","ھاكىم بۇ گىرۋەككە سۈركىلگەن توپنى ئىناۋەتلىك دەپ ھۆكۈم قىلدى.","hakim bu girwekke sürkilgen topni inawetlik dep höküm qildi."]],"据统计":[["据统计，今年经济增长显著。","ستاتىستىكىغا ئاساسەن، بۇ يىل ئىقتىسادىي ئۆسۈش كۆرۈنەرلىك بولدى.","statistikigha asasen, bu yil iqtisadiy ösüsh körünerlik boldi."]],"支承销":[["银行提供支承销服务。","بانكا تىرەك سېتىش مۇلازىمىتىنى تەمىنلەيدۇ.","banka tirek sétish mulazimitini teminleydu."]],"收废站":[["收废站回收各种废旧物品。","ئەسكىپ-تۈگىمەس پونكىتى ھەر خىل ئەسكىپ-تۈگىمەس بۇيۇملارنى قايتا ئىشلىتىشكە ئالىدۇ.","eskip-tügimes ponkiti her xil eskip-tügimes buyumlarni qayta ishlitishke alidu."]],"放低":[["他放低了自己的要求。","ئۇ ئۆز تەلىپىنى تۆۋەنلەتتى.","u öz telipini töwenletti."]],"教安":[["教安是重要的宗教节日。","دىنىي ئامانلىق مۇھىم دىنىي بايرام.","diniy amanliq muhim diniy bayram."]],"教义":[["教义是宗教的核心教导。","دىن تەلىماتى دىننىڭ يادرولۇق ئوقۇتۇشىدۇر.","din telimati dinning yadroluq oqutushidur."]],"叙述性":[["这部小说叙述性强。","بۇ روماننىڭ بايانچانلىقى كۈچلۈك.","bu romanning bayanchanliqi küchlük."]],"教育部长":[["教育部长宣布了新的改革方案。","مائارىپ مىنىستىرى يېڭى ئىسلاھات پىلانىنى ئېلان قىلدى.","maarip ministiri yéngi islahat pilanini élan qildi."]],"敞亮":[["这个房间设计得非常敞亮。","بۇ ئۆينىڭ لايىھىسى ئىنتايىن يورۇق.","bu öyning layihisi intayin yoruq."]],"数字时钟":[["数字时钟显示的时间非常精确。","رەقەملىك سائەت كۆرسىتىدىغان ۋاقىت ئىنتايىن ئېنىق.","reqemlik saet körsitidighan waqit intayin éniq."]],"整脊学":[["整脊学治疗脊椎问题。","پۈتۈن ئومۇرتقا ئىلمى ئومۇرتقا مەسىلىلىرىنى داۋالايدۇ.","pütün omurtqa ilmi omurtqa mesililirini dawalaydu."]],"文康":[["文康是一位优秀的作家。","ۋېنكاڭ ئالاھىدە يازغۇچى.","wénkang alahide yazghuchi."]],"斑嘴鹈鹕":[["斑嘴鹈鹕张开大嘴捕食鱼类。","داغلىق تۇمشۇق سۇقۇن قۇش چوڭ ئاغزىنى ئېچىپ بېلىقلارنى ئوۋلىماقتا.","daghliq tumshuq suqun qush chong aghzini échip béliqlarni owlimaqta."]],"新奥尔良":[["新奥尔良的美食闻名世界。","يېڭى ئورلېئاننىڭ تائاملىرى دۇنياغا داڭلىق.","yéngi orléanning taamliri dunyagha dangliq."]],"新威胁":[["这个新威胁必须引起重视。","بۇ يېڭى تەھدىتكە چوقۇم ئەھمىيەت بېرىش كېرەك.","bu yéngi tehditke choqum ehmiyet bérish kérek."]],"新会区":[["新会区是江门市的区。","شىنخۇي رايونى جياڭمېن شەھىرىنىڭ رايونى.","shinxuy rayoni jyangmén shehirining rayoni."]],"新抚区":[["新抚区是城市的一个区域。","شىنفۇ رايونى شەھەرنىڭ بىر رايونى.","shinfu rayoni sheherning bir rayoni."]],"族长":[["族长负责管理整个家族的事务。","قەبىلە باشلىقى پۈتۈن ئائىلە ئىشلىرىنى باشقۇرۇشقا مەسئۇل.","qebile bashliqi pütün aile ishlirini bashqurushqa mes'ul."]],"旗标":[["旗标用来标记路线。","بايراق بەلگىسى يولنى بەلگىلەشكە ئىشلىتىلىدۇ.","bayraq belgisi yolni belgileshke ishlitilidu."]],"日久岁深":[["日久岁深，两人逐渐产生了感情。","كۈنلەر ئۆتكەنسېرى، ئىككىيلەن تەدرىجىي مۇھەببەت باغلىدى.","künler ötkenséri, ikkiylen tedrijiy muhebbet baghlidi."]],"日冕":[["日冕是太阳大气层的最外层。","قۇياش تاجى قۇياش ئاتموسفېرىسىنىڭ ئەڭ سىرتقى قەۋىتى.","quyash taji quyash atmosférisining eng sirtqi qewiti."]],"旱象":[["旱象是干旱地区的典型特征。","قۇرغاقلىق ئالامىتى قۇرغاق رايونلارنىڭ تىپىك ئالاھىدىلىكى.","qurghaqliq alamiti qurghaq rayonlarning tipik alahidiliki."]],"昂昂溪区":[["昂昂溪区发展迅速。","ئاڭئاڭشى رايونى تېز تەرەققىي قىلماقتا.","ang'angshi rayoni téz tereqqiy qilmaqta."]],"春柳社":[["春柳社是著名的戏剧团体。","چۇنليۇ جەمئىيىتى داڭلىق تىياتىر گۇرۇپپىسى.","chunlyu jem'iyiti dangliq tiyatir guruppisi."]],"春蚕":[["春蚕吐出的丝非常细腻。","باھار پىلە قۇرتى چىقارغان يىپ ئىنتايىن نەپىس.","bahar pile qurti chiqarghan yip intayin nepis."]],"春试":[["他参加了今年的春试。","ئۇ بۇ يىللىق باھار ئىمتىھانىغا قاتناشتى.","u bu yilliq bahar imtihanigha qatnashti."]],"映象文件":[["这个映象文件需要特殊处理。","بۇ ئەكس ئەتتۈرۈش ھۆججىتى ئالاھىدە بىر تەرەپ قىلىشقا موھتاج.","bu eks ettürüsh höjjiti alahide bir terep qilishqa mohtaj."]],"春光明媚":[["春光明媚，让人心情愉悦。","باھار نۇرى پارلاق، كىشىنىڭ كۆڭلىنى خۇشال قىلىدۇ.","bahar nuri parlaq, kishining könglini xushal qilidu."]],"晶圆":[["这种晶圆用于制造芯片。","بۇ خىل كرىستال ياپراقچىسى چىپ ئىشلەپچىقىرىشقا ئىشلىتىلىدۇ.","bu xil kristal yapraqchisi chip ishlepchiqirishqa ishlitilidu."]],"暴风雪":[["北方地区迎来了严重的暴风雪。","شىمالىي رايونلاردا ئېغىر بوران-قار كۈتۈۋېلىندى.","shimaliy rayonlarda éghir boran-qar kütüwélindi."]],"会议室":[["会议室里正在进行讨论。","يىغىن زالىدا مۇزاكىرە ئېلىپ بېرىلىۋاتىدۇ.","yighin zalida muzakire élip bériliwatidu."]],"有方":[["他做事很有方。","ئۇ ئىش قىلغاندا ئىنتايىن ئۇسۇللۇق.","u ish qilghanda intayin usulluq."]],"有线新闻网":[["他经常浏览有线新闻网获取资讯。","ئۇ دائىم سىملىق خەۋەر تورىنى كۆرۈپ ئۇچۇر ئالىدۇ.","u daim simliq xewer torini körüp uchur alidu."]],"有点":[["这个方案有点问题。","بۇ پىلاندا ئازراق مەسىلە بار.","bu pilanda azraq mesile bar."]],"服务规章":[["请遵守服务规章。","مۇلازىمەت قائىدىلىرىگە رىئايە قىلىڭ.","mulazimet qaidilirige riaye qiling."]],"朝鲜战争":[["朝鲜战争对亚洲局势产生了深远影响。","چاۋشيەن ئۇرۇشى ئاسىيا ئەھۋالىغا چوڭقۇر تەسىر كۆرسەتتى.","chawshyen urushi asiya ehwaligha chongqur tesir körsetti."]],"朗文":[["《朗文》是一本经典的英语词典。","«لوڭمەن» كلاسسىك ئىنگلىزچە لۇغەتتۇر.","«longmen» klassik inglizche lughettur."]],"望洋":[["面对大海望洋兴叹。","دېڭىزغا يۈزلىنىپ، پەقەت ھەسرەت بىلەن قاراپ قالدىم.","déngizgha yüzlinip, peqet hesret bilen qarap qaldim."]],"朝鲜族":[["朝鲜族是中国的一个少数民族。","چاۋشيەن مىللىتى جۇڭگونىڭ بىر ئاز سانلىق مىللەت.","chawshyen milliti junggoning bir az sanliq millet."]],"有声有色":[["这场演出表演得有声有色。","بۇ نومۇر ئىنتايىن جانلىق ئورۇنلاندى.","bu nomur intayin janliq orunlandi."]],"木薯淀粉":[["木薯淀粉广泛用于食品加工。","ياغاچ كاساۋا كراخمالى يېمەكلىك پىششىقلاپ ئىشلەشتە كەڭ ئىشلىتىلىدۇ.","yaghach kasawa kraxmali yémeklik pishshiqlap ishleshte keng ishlitilidu."]],"杜集区":[["杜集区是当地重要的经济中心。","دۇجى رايونى يەرلىك مۇھىم ئىقتىساد مەركىزى.","duji rayoni yerlik muhim iqtisad merkizi."]],"杜马":[["这匹杜马在比赛中表现出色。","بۇ دۇما مۇسابىقىدە ئالاھىدە ياخشى نەتىجە كۆرسەتتى.","bu duma musabiqide alahide yaxshi netije körsetti."]],"枇杷":[["枇杷是夏季常见的水果。","بىۋا ياز پەسلىدە كۆپ ئۇچرايدىغان مېۋە.","biwa yaz peslide köp uchraydighan méwe."]],"枉费":[["这次尝试虽然枉费了精力，但仍有收获。","بۇ قېتىمقى سىناش كۈچ-قۇۋۋەتنى بىكار كەتكۈزگەن بولسىمۇ، يەنىلا نەتىجە بار.","bu qétimqi sinash küch-quwwetni bikar ketküzgen bolsimu, yenila netije bar."]],"松明":[["松明是古代常用的照明工具。","سۇڭمىڭ قەدىمكى زامانلاردا كۆپ ئىشلىتىلگەن يورۇتۇش قورالى.","sungming qedimki zamanlarda köp ishlitilgen yorutush qorali."]],"果蔬":[["超市里摆满了新鲜的果蔬。","سۇپەرماركېتتا يېڭى مېۋە-كۆكتاتلار بىلەن تولۇپ كەتكەن.","supermarkétta yéngi méwe-köktatlar bilen tolup ketken."]],"枝繁叶茂":[["这棵树枝繁叶茂，生机勃勃。","بۇ دەرەخنىڭ شاخلىرى كۆپ، يوپۇرماقلىرى قويۇق، ھاياتىي كۈچكە تولغان.","bu derexning shaxliri köp, yopurmaqliri qoyuq, hayatiy küchke tolghan."]],"李天王":[["李天王是佛教中的护法神。","لى تيەنۋاڭ بۇددا دىنىدىكى قوغدىغۇچى ئىلاھ.","li tyenwang budda dinidiki qoghdighuchi ilah."]],"东直门":[["东直门是北京著名的交通枢纽。","دۇڭجىمېن بېيجىڭنىڭ مەشھۇر قاتناش تۈگۈنى.","dungjimén béyjingning meshhur qatnash tügüni."]],"架子猪":[["架子猪是一种专门用于育肥的猪种。","ئىشكاپ چوشقىسى سېمىرتىش ئۈچۈن ئالاھىدە بېقىلىدىغان چوشقا تۈرىدۇر.","ishkap choshqisi sémirtish üchün alahide béqilidighan choshqa türidur."]],"校监":[["校监负责监督学校事务。","مەكتەپ نازارەتچىسى مەكتەپ ئىشلىرىغا نازارەت قىلىشقا مەسئۇل.","mektep nazaretchisi mektep ishlirigha nazaret qilishqa mes'ul."]],"格尔木":[["格尔木位于青海省的西部。","گولمۇد چىڭخەي ئۆلكىسىنىڭ غەربىي قىسمىدا جايلاشقان.","golmud chingxey ölkisining gherbiy qismida jaylashqan."]],"林雕鸮":[["林雕鸮是夜间活动的鸟类。","لىن بۈركۈت ئۈكۈسى كېچىسى پائالىيەت قىلىدىغان قۇش.","lin bürküt üküsi kéchisi paaliyet qilidighan qush."]],"桄榔":[["桄榔是一种高大的棕榈树。","كاۋاڭلار بىر خىل ئېگىز پالمىرا دەرىخى.","kawanglar bir xil égiz palmira derixi."]],"梅氏腺":[["梅氏腺是身体的一部分。","مېي بېزى بەدەننىڭ بىر قىسمى.","méy bézi bedenning bir qismi."]],"栀子":[["栀子是一种常见的观赏花卉。","زىزى بىر خىل كۆپ ئۇچرايدىغان مەنزىرە گۈلى.","zizi bir xil köp uchraydighan menzire güli."]],"条件句":[["如果下雨，比赛就会取消，这是一个条件句。","ئەگەر يامغۇر ياغسا، مۇسابىقە بىكار قىلىنىدۇ، بۇ بىر شەرتلىك جۈملە.","eger yamghur yaghsa, musabiqe bikar qilinidu, bu bir shertlik jümle."]],"梯队":[["梯队常用于描述团队的分层结构。","باسقۇچلۇق ئەترەت كۆپىنچە گۇرۇپپىنىڭ قاتلاملىق قۇرۇلمىسىنى تەسۋىرلەشتە ئىشلىتىلىدۇ.","basquchluq etret köpinche guruppining qatlamliq qurulmisini teswirleshte ishlitilidu."]],"森美兰":[["森美兰是一位优秀的演员。","مورىمېلان ئالاھىدە ئارتىس.","morimélan alahide artis."]],"栈存储器":[["栈存储器用于临时保存数据。","زاڭ ساقلىغۇچ سانلىق مەلۇماتنى ۋاقىتلىق ساقلاشقا ئىشلىتىلىدۇ.","zang saqlighuch sanliq melumatni waqitliq saqlashqa ishlitilidu."]],"植物界":[["植物界包含无数不同种类的植物。","ئۆسۈملۈكلەر دۇنياسى سانسىزلىغان ئوخشىمىغان تۈردىكى ئۆسۈملۈكلەرنى ئۆز ئىچىگە ئالىدۇ.","ösümlükler dunyasi sansizlighan oxshimighan türdiki ösümlüklerni öz ichige alidu."]],"极权主义":[["极权主义强调绝对控制。","قۇتۇپ ھوقۇقچىلىق مۇتلەق كونتروللۇقنى تەكىتلەيدۇ.","qutup hoquqchiliq mutleq kontrolluqni tekitleydu."]],"榴弹发射器":[["士兵使用榴弹发射器进行攻击。","ئەسكەرلەر گرانات ئاتقۇچ ئارقىلىق ھۇجۇم قىلىدۇ.","eskerler granat atquch arqiliq hujum qilidu."]],"枪刺":[["士兵用枪刺刺中了敌人。","ئەسكەر نەيزىنى ئىشلىتىپ دۈشمەنگە سانجىدى.","esker neyzini ishlitip düshmenge sanjidi."]],"楼梯口":[["楼梯口有扶手。","پەلەمپەي ئېغىزىدا تۇتقۇچ بار.","pelempey éghizida tutquch bar."]],"标准像":[["标准像的拍摄需要遵循特定的规范。","ئۆلچەملىك سۈرەت تارتىش ئالاھىدە قائىدىلەرگە ئەمەل قىلىشى كېرەك.","ölchemlik süret tartish alahide qaidilerge emel qilishi kérek."]],"橐龠":[["橐龠是古代的一种鼓风装置。","توقۇلداش كۆرۈكى قەدىمكى دەۋردىكى بىر خىل شامال بېسىش ئۈسكۈنىسى.","toquldash körüki qedimki dewrdiki bir xil shamal bésish üskünisi."]],"枪机":[["枪机的结构直接影响射击精度。","مىلتىق مېخانىزمىنىڭ قۇرۇلمىسى ئوق ئېتىش ئېنىقلىقىغا بىۋاسىتە تەسىر كۆرسىتىدۇ.","miltiq méxanizmining qurulmisi oq étish éniqliqigha biwasite tesir körsitidu."]],"横躺":[["他横躺床上，无法起身。","ئۇ كارىۋاتقا يانپاشلاپ يېتىپ، ئورنىدىن تۇرالماي قالدى.","u kariwatqa yanpashlap yétip, ornidin turalmay qaldi."]],"檀君王":[["檀君王是古代的一位君主。","دانگۇن پادىشاھ قەدىمكى زاماندىكى بىر ھۆكۈمداردۇر.","dangun padishah qedimki zamandiki bir hökümdardur."]],"次文化":[["次文化在年轻人中很流行。","كىچىك مەدەنىيەت ياشلار ئارىسىدا ئىنتايىن مودا.","kichik medeniyet yashlar arisida intayin moda."]],"梼杌":[["梼杌是中国古代神话中的恶兽。","تاۋۋۇ جۇڭگونىڭ قەدىمكى ئەپسانىلىرىدىكى يامان ھايۋاندۇر.","tawwu junggoning qedimki epsaniliridiki yaman haywandur."]],"树突":[["神经元的树突负责接收信号。","نېيرونلارنىڭ دەرەخسىمان تارماقلىرى سىگنال قوبۇل قىلىشقا مەسئۇل.","néyronlarning derexsiman tarmaqliri signal qobul qilishqa mes'ul."]],"欲求":[["她的欲求总是无法满足。","ئۇنىڭ تەلەپ-ئارزۇسى ھەرگىز قاندۇرۇلالمايدۇ.","uning telep-arzusi hergiz qandurulalmaydu."]],"栾城":[["栾城历史悠久，文化底蕴深厚。","لۇەنچېڭ ئۇزۇن تارىخقا ئىگە، مەدەنىيەت ئاساسى چوڭقۇر.","luenchéng uzun tarixqa ige, medeniyet asasi chongqur."]],"歌舞团":[["歌舞团即将开始巡演。","ناخشا-ئۇسسۇل ئانسامبلى يېقىندا سەپەرنى باشلايدۇ.","naxsha-ussul ansambli yéqinda seperni bashlaydu."]],"正道":[["走正道才能成功。","تۈز يولدا مېڭىش ئاندىن مۇۋەپپەقىيەت قازىنىشقا بولىدۇ.","tüz yolda méngish andin muweppeqiyet qazinishqa bolidu."]],"死别":[["他们经历了痛苦的死别。","ئۇلار ئازابلىق ئۆلۈم ئايرىلىشىنى باشتىن كەچۈردى.","ular azabliq ölüm ayrilishini bashtin kechürdi."]],"死士":[["死士愿意为君主牺牲生命。","ئۆلۈمگە تەييار جەڭچىلەر پادىشاھ ئۈچۈن جانلىرىنى پىدا قىلىشقا رازى.","ölümge teyyar jengchiler padishah üchün janlirini pida qilishqa razi."]],"殊途同归":[["殊途同归，最终目标一致。","يوللار ئوخشىمىسىمۇ، ئاخىرقى نىشان بىر.","yollar oxshimisimu, axirqi nishan bir."]],"杀人灭口":[["他担心秘密泄露，决定杀人灭口。","ئۇ سىرنىڭ ئاشكارىلىنىشىدىن قورقۇپ، ئۆلتۈرۈپ ئاغىزىنى تۇتۇشنى قارار قىلدى.","u sirning ashkarilinishidin qorqup, öltürüp aghizini tutushni qarar qildi."]],"每日快报":[["每日快报提供最新的新闻信息。","كۈندىلىك تېز خەۋەر ئەڭ يېڭى خەۋەر ئۇچۇرلىرىنى تەمىنلەيدۇ.","kündilik téz xewer eng yéngi xewer uchurlirini teminleydu."]],"民主党":[["民主党是美国的主要政党之一。","دېموكراتىك پارتىيە ئامېرىكىنىڭ ئاساسلىق پارتىيەلىرىنىڭ بىرىدۇر.","démokratik partiye amérikining asasliq partiyelirining biridur."]],"殒身不恤":[["为了正义，他殒身不恤。","ھەققانىيەت ئۈچۈن ئۇ جانىنى ئايىمىدى.","heqqaniyet üchün u janini ayimidi."]],"归拢":[["把散落的物品归拢到一起。","چېچىلىپ كەتكەن بۇيۇملارنى بىر يەرگە جەم قىلىڭ.","chéchilip ketken buyumlarni bir yerge jem qiling."]],"氰基细菌":[["氰基细菌能在极端环境中生存。","سىيان گۇرۇپپىلىق باكتېرىيەلەر ئەڭ ناچار مۇھىتتا ياشىيالايدۇ.","siyan guruppiliq baktériyeler eng nachar muhitta yashiyalaydu."]],"水菖蒲":[["水菖蒲是一种水生植物。","سۇ ئىرىسى سۇدا ئۆسىدىغان ئۆسۈملۈك.","su irisi suda ösidighan ösümlük."]],"水蒸气":[["水蒸气是液体蒸发后的产物。","سۇ بۇغى سۇيۇقلۇقنىڭ پارلىنىشىدىن كېيىنكى مەھسۇلات.","su bughi suyuqluqning parlinishidin kéyinki mehsulat."]],"民歌手":[["这位民歌手嗓音独特，深受喜爱。","بۇ خەلق ناخشىچىسىنىڭ ئاۋازى ئالاھىدە، كۆپچىلىك ياخشى كۆرىدۇ.","bu xelq naxshichisining awazi alahide, köpchilik yaxshi köridu."]],"江城哈尼族彝族自治县":[["江城哈尼族彝族自治县多民族聚居。","جياڭچېڭ خەنىزۇ-يىزۇ ئاپتونوم ناھىيىسىدە كۆپ مىللەتلەر مەركەزلىشىپ ياشايدۇ.","jyangchéng xenizu-yizu aptonom nahiyiside köp milletler merkezliship yashaydu."]],"江城县":[["江城县以茶叶生产闻名。","جياڭچېڭ ناھىيىسى چاي ئىشلەپچىقىرىش بىلەن داڭلىق.","jyangchéng nahiyisi chay ishlepchiqirish bilen dangliq."]],"江夏":[["江夏是历史名城，文化底蕴深厚。","جياڭشيا تارىخىي شەھەر بولۇپ، مەدەنىيەت ئاساسى چوڭقۇر.","jyangshya tarixiy sheher bolup, medeniyet asasi chongqur."]],"江山市":[["江山市历史悠久，文化深厚。","جياڭشەن شەھىرىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى چوڭقۇر.","jyangshen shehirining tarixi uzun, medeniyiti chongqur."]],"决口":[["决口会导致严重的洪灾。","دەريا بۆسۈشى ئېغىر سۇ ئاپىتىگە سەۋەب بولىدۇ.","derya bösüshi éghir su apitige seweb bolidu."]],"江华县":[["江华县历史悠久，文化丰富。","جياڭخۇا ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى باي.","jyangxua nahiyisining tarixi uzun, medeniyiti bay."]],"江苏":[["江苏是中国东部的重要省份。","جياڭسۇ جۇڭگونىڭ شەرقىي قىسمىدىكى مۇھىم ئۆلكە.","jyangsu junggoning sherqiy qismidiki muhim ölke."]],"气锤":[["气锤是工业中常用的工具。","ھاۋا بولقىسى سانائەتتە كۆپ ئىشلىتىلىدىغان قورال.","hawa bolqisi sanaette köp ishlitilidighan qoral."]],"沙拉":[["这道沙拉口感清新。","بۇ سالاتنىڭ تەمى تازا.","bu salatning temi taza."]],"沿路":[["沿路欣赏美景。","يول بويىچە گۈزەل مەنزىرىلەردىن ھۇزۇرلان.","yol boyiche güzel menzirilerdin huzurlan."]],"没完没了":[["他的抱怨没完没了。","ئۇنىڭ شىكايىتى ئاخىرلاشمايدۇ.","uning shikayiti axirlashmaydu."]],"泃河":[["泃河贯穿整个县城。","جۈخې دەرياسى پۈتۈن ناھىيە بازىرىدىن ئۆتىدۇ.","jüxé deryasi pütün nahiye baziridin ötidu."]],"波士顿红袜":[["波士顿红袜队是美国职业棒球队。","بوستون رېد سوكس كوماندىسى ئامېرىكىنىڭ كەسپىي بېسبول كوماندىسىدۇر.","boston réd soks komandisi amérikining kespiy bésbol komandisidur."]],"泰迪熊":[["泰迪熊是经典的儿童玩具。","تەيدى ئېيىقچىسى كلاسسىك بالىلار ئويۇنچۇقى.","teydi éyiqchisi klassik balilar oyunchuqi."]],"洲际导弹":[["洲际导弹的射程可达数千公里。","قىتئەلەرئارا بومبانىڭ ئېتىلىش ئارىلىقى نەچچە مىڭ كىلومېتىرغا يېتىدۇ.","qit'eler'ara bombaning étilish ariliqi nechche ming kilométirgha yétidu."]],"海沧":[["海沧是厦门的一个繁华区域。","خەيتساڭ شياڭمېننىڭ گۈللەنگەن رايونلىرىنىڭ بىرىدۇر.","xeytsang shyangménning güllengen rayonlirining biridur."]],"海产":[["海产包括各种海鲜。","دېڭىز مەھسۇلاتلىرى ھەر خىل دېڭىز يېمەكلىكلىرىنى ئۆز ئىچىگە ئالىدۇ.","déngiz mehsulatliri her xil déngiz yémekliklirini öz ichige alidu."]],"海事处":[["海事处为渔民提供咨询服务。","دېڭىز ئىشلىرى بۆلۈمى بېلىقچىلارغا مەسلىھەت مۇلازىمىتى تەمىنلەيدۇ.","déngiz ishliri bölümi béliqchilargha meslihet mulazimiti teminleydu."]],"消化不良":[["消化不良会导致腹部不适。","ھەزىم قىلىش يېتىشمەسلىكى قورساقنىڭ ناچارلىشىشىغا سەۋەب بولىدۇ.","hezim qilish yétishmesliki qorsaqning nacharlishishigha seweb bolidu."]],"深层次":[["问题需要深层次解决。","مەسىلىنى چوڭقۇر قاتلامدا ھەل قىلىش كېرەك.","mesilini chongqur qatlamda hel qilish kérek."]],"浪人":[["他是一个流浪的浪人。","ئۇ سەرسان بولۇپ يۈرىدىغان بىر سەرگەردان.","u sersan bolup yüridighan bir sergerdan."]],"清兵":[["清兵在战场上英勇作战。","چىڭ ئەسكەرلىرى جەڭ مەيدانىدا قەھرىمانلارچە جەڭ قىلدى.","ching eskerliri jeng meydanida qehrimanlarche jeng qildi."]],"清水县":[["清水县历史悠久，文化资源丰富。","چىڭشۈي ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيەت بايلىقلىرى مول.","chingshüy nahiyisining tarixi uzun, medeniyet bayliqliri mol."]],"滂沱大雨":[["滂沱大雨持续了整整一个下午。","زىل-زىلە يامغۇر پۈتۈن بىر چۈشتىن كېيىنكى ۋاقىتقىچە داۋاملاشتى.","zil-zile yamghur pütün bir chüshtin kéyinki waqitqiche dawamlashti."]],"滋贺县":[["滋贺县位于日本关西地区。","شىگا ناھىيىسى ياپونىيەنىڭ كانساي رايونىدا جايلاشقان.","shiga nahiyisi yaponiyening kansay rayonida jaylashqan."]],"滋养":[["母乳能很好地滋养婴儿。","ئانا سۈتى بوۋاقنى ياخشى ئوزۇقلاندۇرالايدۇ.","ana süti bowaqni yaxshi ozuqlanduralaydu."]],"温家宝":[["温家宝曾担任中国总理职务。","ۋېن جياباۋ ئىلگىرى جۇڭگو باش مىنىستىرى ۋەزىپىسىنى ئۆتىگەن.","wén jyabaw ilgiri junggo bash ministiri wezipisini ötigen."]],"汤阴":[["汤阴是河南省的一个地名。","تاڭيىن خېنەن ئۆلكىسىدىكى بىر يەر نامىدۇر.","tangyin xénen ölkisidiki bir yer namidur."]],"溏便":[["孩子今天拉了溏便。","بالا بۈگۈن سۇس نەجەسەت قىلدى.","bala bügün sus nejeset qildi."]],"滴答声":[["滴答声在安静的房间里格外清晰。","تىق-تىق ئاۋاز جىمجىت ئۆيدە ئالاھىدە ئېنىق ئاڭلىنىدۇ.","tiq-tiq awaz jimjit öyde alahide éniq anglinidu."]],"满口称赞":[["老师对他的表现满口称赞。","ئوقۇتقۇچى ئۇنىڭ ئىپادىسىنى ئاغزى-ئاغزىغا چىقىرىپ ماختاپ كەتتى.","oqutquchi uning ipadisini aghzi-aghzigha chiqirip maxtap ketti."]],"满口脏话":[["他满口脏话，令人反感。","ئۇ ئاغزى-ئاغزىغا چىقىرىپ يامان سۆزلەيدۇ، كىشىلەرنى بىزار قىلىدۇ.","u aghzi-aghzigha chiqirip yaman sözleydu, kishilerni bizar qilidu."]],"济州":[["济州是韩国著名的旅游岛屿。","جىجۇ كورېيەنىڭ مەشھۇر ساياھەت ئارىلىدۇر.","jiju koréyening meshhur sayahet arilidur."]],"滨海县":[["滨海县以丰富的海洋资源闻名。","بىنھەي ناھىيەسى مول دېڭىز بايلىقلىرى بىلەن داڭلىق.","binhey nahiyesi mol déngiz bayliqliri bilen dangliq."]],"滤嘴":[["香烟的滤嘴可以过滤部分有害物质。","تاماكا سۈزگۈچى زىيانلىق ماددىلارنىڭ بىر قىسمىنى سۈزەلەيدۇ.","tamaka süzgüchi ziyanliq maddilarning bir qismini süzeleydu."]],"火烛":[["古代人用火烛来照明。","قەدىمكىلەر يورۇتۇش ئۈچۈن ئوت شاملىرىنى ئىشلەتكەن.","qedimkiler yorutush üchün ot shamlirini ishletken."]],"灰胸竹鸡":[["灰胸竹鸡在竹林中活动。","كۈمۈشسىمان كۆكرەك بامبۇك توخۇسى بامبۇكزارلىقتا ھەرىكەتلىنىدۇ.","kümüshsiman kökrek bambuk toxusi bambukzarliqta heriketlinidu."]],"灰蒙蒙":[["天空灰蒙蒙的，没有阳光。","ئاسمان كۈمۈشسىمان تۇمانلىق، قۇياش نۇرى يوق.","asman kümüshsiman tumanliq, quyash nuri yoq."]],"灰鹀":[["灰鹀的叫声在清晨格外清晰。","كۈلرەڭ سېرىقچى قۇشنىڭ ئاۋازى تاڭ سەھەردە ئالاھىدە ئېنىق.","külreng sériqchi qushning awazi tang seherde alahide éniq."]],"炸丸子":[["他做了炸丸子。","ئۇ پىشۇرۇلغان كۆمەچ ياسىدى.","u pishurulghan kömech yasidi."]],"乌孜别克":[["乌孜别克族拥有独特的音乐传统。","ئۆزبېك مىللىتى ئۆزىگە خاس مۇزىكا ئەنئەنىسىگە ئىگە.","özbék milliti özige xas muzika en'enisige ige."]],"乌孙国":[["乌孙国是古代丝绸之路上的重要国家。","ئۇسۇن دۆلىتى قەدىمكى يىپەك يولىدىكى مۇھىم دۆلەت ئىدى.","usun döliti qedimki yipek yolidiki muhim dölet idi."]],"乌拉圭":[["乌拉圭是南美洲的一个足球强国。","ئۇرۇگۋاي جەنۇبىي ئامېرىكىدىكى بىر پۇتبول كۈچلۈك دۆلىتىدۇر.","urugway jenubiy amérikidiki bir putbol küchlük dölitidur."]],"为上":[["以他人为上。","باشقىلارنى ئۆزىدىن ئۈستۈن بىلىش.","bashqilarni özidin üstün bilish."]],"熟透":[["苹果熟透了，轻轻一碰就掉下来。","ئالما پىشىپ يېتىلدى، ئاستا تەگسىلا چۈشۈپ كېتىدۇ.","alma piship yétildi, asta tegsila chüshüp kétidu."]],"烟熏":[["烟熏食物香气扑鼻，让人食欲大开。","تاماكا ئىسىدە پىشۇرۇلغان يېمەكلىك خۇش پۇراق تارىتىپ، كىشىنىڭ ئىشتىھاسىنى ئاچىدۇ.","tamaka iside pishurulghan yémeklik xush puraq taritip, kishining ishtihasini achidu."]],"烟花厂":[["这家烟花厂生产了许多精美的烟花。","بۇ ئاتەش ئويۇنى زاۋۇتى نۇرغۇن گۈزەل ئاتەش ئويۇنلىرىنى ئىشلەپچىقاردى.","bu atesh oyuni zawuti nurghun güzel atesh oyunlirini ishlepchiqardi."]],"为爱鼓掌":[["他们为爱鼓掌，表达彼此的爱意。","ئۇلار مۇھەببەت ئۈچۈن چاۋاك چېلىپ، بىر-بىرىگە بولغان مۇھەببىتىنى ئىپادىلەيدۇ.","ular muhebbet üchün chawak chélip, bir-birige bolghan muhebbitini ipadileydu."]],"焙粉":[["焙粉是将粉末状物料加热干燥。","بېيفېن كۇكۇن ھالىتىدىكى ماتېرىياللارنى قىزىتىپ قۇرۇتۇش.","béyfén kukun halitidiki matériyallarni qizitip qurutush."]],"焚琴煮鹤":[["他竟焚琴煮鹤，实在令人惋惜。","ئۇ ھەتتا چىڭنى كۆيدۈرۈپ تۇرنى پىشۇردى، ھەقىقەتەن ئېچىنىشلىق.","u hetta chingni köydürüp turni pishurdi, heqiqeten échinishliq."]],"无处可寻":[["这个答案无处可寻。","بۇ جاۋابنى ھېچقايەردىن ئىزدەپ تاپقىلى بولمايدۇ.","bu jawabni héchqayerdin izdep tapqili bolmaydu."]],"牛皮癣":[["牛皮癣是一种慢性皮肤疾病。","تېرە كېسىلى بولسا بىر خىل سۈرۈنكىلىك تېرە كېسەللىكى.","tére késili bolsa bir xil sürünkilik tére késelliki."]],"灯火通明":[["节日里，街道灯火通明。","بايرام كۈنلىرى كوچىلار چىراغ نۇرى بىلەن پارلاپ تۇرىدۇ.","bayram künliri kochilar chiragh nuri bilen parlap turidu."]],"炉边":[["炉边放着几本烹饪书籍，供人参考。","ئوچاق يېنىغا بىر قانچە پارچە ئاشپەزلىك كىتابى قويۇلغان، كىشىلەر پايدىلىنىشى ئۈچۈن.","ochaq yénigha bir qanche parche ashpezlik kitabi qoyulghan, kishiler paydilinishi üchün."]],"争强好胜":[["他性格争强好胜，总是想超越他人。","ئۇنىڭ خاراكتېرى كۈچلۈك ۋە غەلىبە تەلەپ قىلىدىغان بولۇپ، دائىم باشقىلاردىن ئېشىپ كېتىشنى خالايدۇ.","uning xaraktéri küchlük we ghelibe telep qilidighan bolup, daim bashqilardin éship kétishni xalaydu."]],"狐蝠":[["这种狐蝠会发出超声波。","بۇ خىل تۈلكە يارقاناتى ئۇلترا ئاۋاز دولقۇنى چىقىرىدۇ.","bu xil tülke yarqanati ultra awaz dolquni chiqiridu."]],"特利":[["特利是公司的创始人。","تېررىي شىركەتنىڭ قۇرغۇچىسىدۇر.","térriy shirketning qurghuchisidur."]],"玉竹":[["玉竹是一种观赏性很强的植物。","يۈجۇ بىر خىل تاماشىبىنلىق قىممىتى يۇقىرى ئۆسۈملۈك.","yüju bir xil tamashibinliq qimmiti yuqiri ösümlük."]],"现场会":[["公司举办了产品现场会。","شىركەت مەھسۇلات مەيدان يىغىنى ئۆتكۈزدى.","shirket mehsulat meydan yighini ötküzdi."]],"玻璃纸":[["她用玻璃纸包装了礼物。","ئۇ سوۋغاتنى ئەينەك قەغەز بىلەن قاپلىدى.","u sowghatni eynek qeghez bilen qaplidi."]],"玉屏侗族自治县":[["玉屏侗族自治县风景优美。","يۈپىڭ دۇڭزۇ ئاپتونوم ناھىيىسىنىڭ مەنزىرىسى گۈزەل.","yüping dungzu aptonom nahiyisining menzirisi güzel."]],"玛仁糖":[["玛仁糖是一种传统的糖果。","مارېن تاتلىقلىقى ئەنئەنىۋى بىر تاتلىقلىق.","marén tatliqliqi en'eniwi bir tatliqliq."]],"环江":[["环江是一条流经广西的河流。","خۇەنجياڭ گۇاڭشىدىن ئېقىپ ئۆتىدىغان بىر دەريا.","xuenjyang guangshidin éqip ötidighan bir derya."]],"瓶胆":[["瓶胆用于保温瓶内部。","ئاپتوقنىڭ ئىچكى قېپى تېرموس ئىچىدە ئىشلىتىلىدۇ.","aptoqning ichki qépi térmos ichide ishlitilidu."]],"瓶领":[["瓶领部分容易磨损。","ئاپتوقنىڭ بويۇن قىسمى ئاسانلىقچە ئېشىنىپ كېتىدۇ.","aptoqning boyun qismi asanliqche éshinip kétidu."]],"甄拔":[["公司注重甄拔人才。","شىركەت ئىختىساسلىق ئادەملەرنى تاللاشقا ئەھمىيەت بېرىدۇ.","shirket ixtisasliq ademlerni tallashqa ehmiyet béridu."]],"生死有命":[["生死有命，富贵在天。","ھايات-مامات تەقدىردىن، بايلىق تەڭرىدىن.","hayat-mamat teqdirdin, bayliq tengridin."]],"生物专一性":[["这种酶具有高度的生物专一性。","بۇ ferment يۇقىرى دەرىجىدىكى biologik xoslikكە ئىگە.","bu ferment yuqiri derijidiki biologik xoslikke ige."]],"田鹀":[["田鹀是一种小型的鸟类。","دېڭىز قۇشى كىچىك تىپتىكى قۇش تۈرى.","déngiz qushi kichik tiptiki qush türi."]],"留有":[["合同中留有补充条款的余地。","توختامدا تولۇقلىما ماددىلار ئۈچۈن ئورۇن قالدۇرۇلغان.","toxtamda toluqlima maddilar üchün orun qaldurulghan."]],"异丙醇":[["异丙醇常用于消毒和溶剂。","ئىزوپروپىل ئالسپىرت كۆپىنچە دېزىنفېكسىيە ۋە ئېرىتكۈچتە ئىشلىتىلىدۇ.","izopropil alspirt köpinche dézinféksiye we éritküchte ishlitilidu."]],"番禺":[["番禺是广州历史悠久的老城区。","پانيۈ گۇاڭجۇنىڭ ئۇزۇن تارىخقا ئىگە كونا شەھەر رايونى.","panyü guangjuning uzun tarixqa ige kona sheher rayoni."]],"画舫":[["画舫是一种装饰华丽的游船。","رەسىملىك كېمە زىننەتلىك ساياھەت كېمىسىنىڭ بىر تۈرى.","resimlik kéme zinnetlik sayahet kémisining bir türi."]],"癞疮":[["这种癞疮传染性很强。","بۇ خىل يارا يۇقۇملۇق كۈچى بەك كۈچلۈك.","bu xil yara yuqumluq küchi bek küchlük."]],"当权":[["当权者应公正对待百姓。","ھوقۇق تۇتقۇچىلار خەلققە ئادىل مۇئامىلە قىلىشى كېرەك.","hoquq tutquchilar xelqqe adil muamile qilishi kérek."]],"当涂县":[["当涂县历史悠久，文化丰富。","داتۇڭ ناھىيىسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى مول.","datung nahiyisining tarixi uzun, medeniyiti mol."]],"发达国":[["发达国家通常拥有较高生活水平。","تەرەققىي تاپقان دۆلەتلەر ئادەتتە يۇقىرى تۇرمۇش سەۋىيىسىگە ئىگە.","tereqqiy tapqan döletler adette yuqiri turmush sewiyisige ige."]],"白饭":[["他吃了一碗白饭。","ئۇ بىر چىنە ئاق گۈرۈچ يېدى.","u bir chine aq gürüch yédi."]],"白鹭":[["白鹭在湖边优雅地飞翔。","ئاق كۆلەڭ كۆل بويىدا نەپىس ئۇچىدۇ.","aq köleng köl boyida nepis uchidu."]],"百济":[["百济是古代朝鲜半岛的一个国家。","بەيجى قەدىمكى كورېيە يېرىم ئارىلىدىكى بىر دۆلەت ئىدى.","beyji qedimki koréye yérim arilidiki bir dölet idi."]],"百炼成钢":[["宝剑锋从磨砺出，梅花香自苦寒来，百炼成钢。","گۆھەرنىڭ ئۆتكۈرلۈكى سۇۋاشتىن چىقىدۇ، ئۆرۈكنىڭ خۇش پۇرىقى قاتتىق سوغۇقتىن كېلىدۇ، يۈز قېتىم سوقۇلۇپ پولات بولىدۇ.","göherning ötkürlüki suwashtin chiqidu, örükning xush puriqi qattiq soghuqtin kélidu, yüz qétim soqulup polat bolidu."]],"百眼巨人":[["神话中的百眼巨人拥有无数双眼睛。","ئەپسانىدىكى يۈز كۆزلۈك گىگانت چەكسىز كۆزلەرگە ئىگە.","epsanidiki yüz közlük gigant cheksiz közlerge ige."]],"硫酸铝":[["硫酸铝可用于水处理。","سۇلفات ئاليۇمىنىي سۇ بىر تەرەپ قىلىشتا ئىشلىتىلىدۇ.","sulfat alyuminiy su bir terep qilishta ishlitilidu."]],"研判":[["专家对经济形势进行了深入研判。","مۇتەخەسسىسلەر ئىقتىساد ۋەزىيىتى ئۈستىدە چوڭقۇر تەتقىق قىلدى.","mutexessisler iqtisad weziyiti üstide chongqur tetqiq qildi."]],"碾碎":[["这些谷物经过碾碎后变成了面粉。","بۇ ئاشلىقلار ئۇيۇلغاندىن كېيىن ئۇنغا ئايلاندى.","bu ashliqlar uyulghandin kéyin ungha aylandi."]],"磨穿铁砚":[["他发誓要磨穿铁砚才罢休。","ئۇ تۆمۈر ھۆججەت تاختىسىنى تېشىپ چىقمىغۇچە توختىمايمەن دەپ قەسەم قىلدى.","u tömür höjjet taxtisini téship chiqmighuche toxtimaymen dep qesem qildi."]],"磷灰粉":[["磷灰粉用于制造肥料和陶瓷。","فوسفورىت ئۇنى ئوغۇت ۋە ساپال بۇيۇملار ياساشتا ئىشلىتىلىدۇ.","fosforit uni oghut we sapal buyumlar yasashta ishlitilidu."]],"矿灯":[["矿灯为地下作业提供了必要照明。","كان چىرىغى يەر ئاستى مەشغۇلاتىغا زۆرۈر يورۇتۇش بىلەن تەمىنلەيدۇ.","kan chirighi yer asti meshghulatigha zörür yorutush bilen teminleydu."]],"纯褐鹱":[["这种纯褐鹱很稀有。","بۇ خىل پۈتۈن قوڭۇر چاچقۇچ ناھايىتى كام ئۇچرايدۇ.","bu xil pütün qongur chachquch nahayiti kam uchraydu."]],"细胞器":[["细胞器是细胞内执行特定功能的结构。","ھۈجەيرە ئورگانىدىلىرى ھۈجەيرە ئىچىدە ئالاھىدە فۇنكسىيە ئىجرا قىلىدىغان قۇرۇلمىلاردۇر.","hüjeyre organidiliri hüjeyre ichide alahide funksiye ijra qilidighan qurulmilardur."]],"索尔兹伯里平原":[["索尔兹伯里平原是英国的古老遗迹地。","سولزبېرى تۈزلەڭلىكى ئەنگلىيەنىڭ قەدىمكى خارابىلىرى جايىدۇر.","solzbéri tüzlengliki engliyening qedimki xarabiliri jayidur."]]};
